const config = {
  "previewFeatures": [
    "postgresqlExtensions"
  ],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  previewFeatures = [\"postgresqlExtensions\"]\n  output          = \"../generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum UserStatus {\n  INACTIVE\n  ACTIVE\n  BLOCKED\n  PENDING\n  BANNED\n  ABSENT\n}\n\nenum UserCategory {\n  INTERNAL\n  CLIENT\n  SUBCONTRACTOR\n}\n\nenum WorkTimeType {\n  FULL_TIME\n  PART_TIME\n}\n\nenum ContractType {\n  CDI\n  CDD\n  INTERIM\n  STAGE\n}\n\nenum FileAssetVisibility {\n  PRIVATE\n  INTERNAL\n  PUBLIC\n}\n\nenum FileAssetStatus {\n  ACTIVE\n  DELETED\n  ARCHIVED\n}\n\nenum FileAssetVersionStatus {\n  ACTIVE\n  SUPERSEDED\n  ARCHIVED\n  LEGAL_HOLD\n}\n\nenum ReportJobStatus {\n  PENDING\n  RUNNING\n  COMPLETED\n  FAILED\n}\n\nenum ReportOutputFormat {\n  PDF\n  EXCEL\n  CSV\n}\n\nenum ReportScheduleFrequency {\n  DAILY\n  WEEKLY\n  MONTHLY\n  QUARTERLY\n}\n\nenum EnrollmentStatus {\n  PENDING\n  VALIDATED\n  REJECTED\n  COMPLETED\n  ARCHIVED\n}\n\n/// Vue CRM formations catalogue (hors Enrollment LMS cours).\nenum CandidatureStatus {\n  /// Dossier en saisie, pièces incomplètes possibles.\n  DRAFT\n  /// Envoyé aux services / prêt pour instruction.\n  SUBMITTED\n  /// Retour instructeur pièces manquantes ou invalides.\n  MISSING_DOCUMENTS\n  VALIDATION_PENDING\n  PENDING_CNAPS\n  CNAPS_APPROVED\n  CNAPS_REJECTED\n  /// Dossier administratif conforme : apte à être placé sur une session.\n  VALIDATED\n  /// Formation suivie, examen réussi et attestation délivrée.\n  COMPLETED\n  REJECTED\n  ARCHIVED\n}\n\nenum FormationExamOutcome {\n  PENDING\n  PASSED\n  FAILED\n  ABSENT\n}\n\nenum FormationExamStatus {\n  PLANNED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nenum CandidatureSource {\n  MANUAL\n  LEAD\n  LANDING_SESSION\n}\n\nenum FormationSessionEnrollmentStatus {\n  CONFIRMED\n  WAITLIST\n  CANCELLED\n}\n\n/// Créneau journalier suivi formation (émargement matin / soir).\nenum FormationSessionDaySlot {\n  MORNING\n  EVENING\n}\n\nenum FormationSessionEmargementStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n}\n\n/// WF-18 — cycle de justification d'absence (uniquement si status = ABSENT).\nenum AbsenceJustificationStatus {\n  UNJUSTIFIED\n  JUSTIFICATION_REQUESTED\n  JUSTIFIED\n  RESOLVED\n}\n\n/// WF-08 — cycle convention/contrat de formation (par participant).\nenum SessionConventionStatus {\n  GENERATED\n  SENT\n  VIEWED\n  SIGNED\n  ARCHIVED\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  EXCUSED\n}\n\nenum UserBusinessLabel {\n  COLLABORATEUR\n  FORMATEUR\n}\n\n/// Service / équipe interne à l’école de formation (pas une entité juridique ni une « unité » multi-tenant GSMS).\nenum SchoolInternalService {\n  /// Pool formateurs et intervenants.\n  TRAINER_POOL\n  /// Coordination pédagogique, programmes, qualité.\n  PEDAGOGICAL\n  /// RH, administration, support.\n  HR_ADMIN\n  /// Direction de l'établissement (gérant, directeur, équipe de pilotage).\n  DIRECTION\n}\n\nenum EquipmentStatus {\n  AVAILABLE\n  IN_USE\n  MAINTENANCE\n  OUT_OF_SERVICE\n}\n\nenum EquipmentMaintenanceStatus {\n  SCHEDULED\n  IN_PROGRESS\n  COMPLETED\n  OVERDUE\n}\n\nenum StockMovementType {\n  IN\n  OUT\n  TRANSFER\n}\n\nmodel LandingConfig {\n  id String @id @default(uuid())\n\n  sections Json    @default(\"[]\") // Stocke les sections dynamiques (Hero, Sheets, etc.)\n  enabled  Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel User {\n  id       String     @id @default(uuid())\n  email    String     @unique\n  password String?\n  country  String?\n  timezone String?\n  name     String?\n  roleId   String\n  status   UserStatus @default(INACTIVE)\n\n  createdAt               DateTime      @default(now())\n  updatedAt               DateTime      @updatedAt\n  lastSignInAt            DateTime?\n  emailVerifiedAt         DateTime?\n  isTrashed               Boolean       @default(false)\n  avatar                  String?\n  firstName               String?\n  lastName                String?\n  phone                   String?\n  proEmail                String?       @unique\n  userCategory            UserCategory  @default(INTERNAL)\n  subcontractorId         String?\n  jobFunction             String?\n  jobPositionId           String?\n  qualification           String?\n  birthDate               DateTime?\n  birthPlace              String?\n  nationality             String?\n  socialSecurityNumber    String?\n  cniNumber               String?\n  residencePermitNumber   String?\n  residencePermitExpiry   DateTime?\n  contractType            ContractType?\n  workTimeType            WorkTimeType?\n  contractStartDate       DateTime?\n  contractEndDate         DateTime?\n  address                 String?\n  city                    String?\n  postalCode              String?\n  carteProNumber          String?\n  carteProExpiry          DateTime?\n  isSchedulable           Boolean       @default(true)\n  /// Présentation courte affichée sur le landing (#trainers) et fiches publiques équipe.\n  landingPresentation     String?       @db.Text\n  documentCni             String?\n  documentAssurance       String?\n  documentResidencePermit String?\n  documentCartePro        String?\n  invitedByUserId         String?\n  isProtected             Boolean       @default(false)\n\n  role        UserRole    @relation(fields: [roleId], references: [id])\n  jobPosition RhPosition? @relation(fields: [jobPositionId], references: [id], onDelete: SetNull)\n  systemLog   SystemLog[]\n  accounts    Account[]\n  Session     Session[]\n\n  // LMS relations\n  courses                  Course[]\n  userProgress             UserProgress[]\n  purchases                Purchase[]\n  stripeCustomer           StripeCustomer?\n  activitiesModified       Activity[]         @relation(\"ActivityModifier\")\n  chaptersReviewed         Chapter[]          @relation(\"ChapterReviewer\")\n  activitiesReviewed       Activity[]         @relation(\"ActivityReviewer\")\n  quizQuestionBanksCreated QuizQuestionBank[] @relation(\"QuizBankCreator\")\n\n  instructorSessions TrainingSession[]      @relation(\"Instructor\")\n  enrollments        Enrollment[]\n  attendances        Attendance[]\n  grades             Grade[]\n  submissions        AssignmentSubmission[]\n  quizAttempts       QuizAttempt[]\n\n  formationSessionParticipants      FormationSessionParticipant[]\n  formationSessionEmargementsMarked FormationSessionEmargement[]  @relation(\"FormationSessionEmargementMarkedBy\")\n  formationAttestations             FormationAttestation[]\n  candidatures                      Candidature[]\n  complianceDossiers                ComplianceDossier[]           @relation(\"ComplianceDossierUser\")\n  complianceItemsValidated          ComplianceDossierItem[]       @relation(\"ComplianceItemValidator\")\n  fundingCasesAsLearner             FundingCase[]                 @relation(\"FundingCaseLearner\")\n  evidenceAsLearner                 Evidence[]                    @relation(\"EvidenceLearner\")\n  evidenceAsTrainer                 Evidence[]                    @relation(\"EvidenceTrainer\")\n  documentRequestsRequested         DocumentRequest[]             @relation(\"DocumentRequestRequester\")\n  complianceEventsActed             ComplianceItemEvent[]         @relation(\"ComplianceEventActor\")\n  /**\n   * Sessions formation CRM dont cet utilisateur est le formateur référent.\n   */\n  formationSessionsTrained          FormationSession[]            @relation(\"FormationSessionTrainer\")\n  /**\n   * Sessions dont cet utilisateur modère le chat pédagogique.\n   */\n  formationSessionsModerated        FormationSession[]            @relation(\"FormationSessionModerator\")\n\n  certificates    UserCertificate[]\n  discussions     Discussion[]\n  comments        Comment[]\n  discussionVotes DiscussionVote[]\n  commentVotes    CommentVote[]\n\n  trails                   Trail[]\n  trailRuns                TrailRun[]\n  apiTokens                ApiToken[]\n  webhooks                 WebhookEndpoint[]\n  businessRoles            UserBusinessRole[]\n  collaborateurProfile     CollaborateurProfile?\n  formateurProfile         FormateurProfile?\n  landingTeamOffer         LandingTeamOffer?\n  managedCollaborateurs    CollaborateurProfile[]      @relation(\"CollaborateurManager\")\n  createdFileAssets        FileAsset[]                 @relation(\"FileAssetCreatedBy\")\n  createdFileAssetVersions FileAssetVersion[]          @relation(\"FileAssetVersionCreatedBy\")\n  requestedReportJobs      ReportGenerationJob[]       @relation(\"ReportJobsRequested\")\n  requestedAiRuns          AiRun[]                     @relation(\"AiRunsRequested\")\n  reviewedAiArtifacts      AiArtifact[]                @relation(\"AiArtifactReviewed\")\n  assignedSupportTickets   SupportTicket[]             @relation(\"SupportTicketAssignee\")\n  createdSupportTickets    SupportTicket[]             @relation(\"SupportTicketCreatedBy\")\n  ticketComments           TicketComment[]             @relation(\"TicketCommentAuthor\")\n  ticketAttachments        TicketAttachment[]          @relation(\"TicketAttachmentUploader\")\n  helpArticlesAuthored     HelpArticle[]               @relation(\"HelpArticleAuthor\")\n  assignedQualityIncidents QualityIncident[]           @relation(\"QualityIncidentAssignee\")\n  reportedQualityIncidents QualityIncident[]           @relation(\"QualityIncidentReporter\")\n  notificationPreference   UserNotificationPreference?\n\n  inAppNotifications      InAppNotification[]\n  chatParticipants        ChatParticipant[]\n  chatMessages            ChatMessage[]\n  chatInvitationsReceived ChatInvitation[]    @relation(\"ChatInvitationInvitee\")\n  chatInvitationsSent     ChatInvitation[]    @relation(\"ChatInvitationInviter\")\n\n  rhTeamsLed                 RhTeam[]           @relation(\"RhTeamLeader\")\n  rhTeamMemberships          RhTeamMember[]\n  rhOrgUnitsManaged          RhOrgUnit[]        @relation(\"RhOrgUnitManager\")\n  rhAbsences                 RhAbsence[]\n  rhAbsencesValidated        RhAbsence[]        @relation(\"RhAbsenceValidatedBy\")\n  venueRoomBookingsOrganized VenueRoomBooking[] @relation(\"VenueRoomBookingOrganizer\")\n\n  @@index([invitedByUserId])\n  @@index([roleId])\n  @@index([jobPositionId])\n  @@index([status])\n}\n\nmodel FileAsset {\n  id               String              @id @default(uuid())\n  module           String\n  entityType       String\n  entityId         String?\n  category         String?\n  originalName     String\n  mimeType         String\n  size             Int\n  issuedAt         DateTime?\n  expiresAt        DateTime?\n  issuedBy         String?\n  documentRef      String?\n  storageKey       String              @unique\n  url              String\n  visibility       FileAssetVisibility @default(PRIVATE)\n  status           FileAssetStatus     @default(ACTIVE)\n  provider         String              @default(\"s3\")\n  metadata         Json?               @default(\"{}\")\n  createdById      String?\n  currentVersionId String?             @unique\n  archivedAt       DateTime?\n  archiveReason    String?\n  legalHold        Boolean             @default(false)\n  retentionUntil   DateTime?\n  createdAt        DateTime            @default(now())\n  updatedAt        DateTime            @updatedAt\n  deletedAt        DateTime?\n\n  createdBy              User?                        @relation(\"FileAssetCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  currentVersion         FileAssetVersion?            @relation(\"FileAssetCurrentVersion\", fields: [currentVersionId], references: [id], onDelete: SetNull)\n  versions               FileAssetVersion[]           @relation(\"FileAssetVersions\")\n  reportJobs             ReportGenerationJob[]\n  complianceDossierItems ComplianceDossierItem[]\n  complianceItemEvents   ComplianceItemEvent[]\n  ticketAttachments      TicketAttachment[]\n  sessionConventions     FormationSessionConvention[]\n\n  @@index([module, entityType, entityId])\n  @@index([status, visibility])\n  @@index([createdById])\n  @@index([archivedAt])\n}\n\nmodel FileAssetVersion {\n  id            String                 @id @default(uuid())\n  fileAssetId   String\n  versionNumber Int\n  storageKey    String                 @unique\n  url           String\n  mimeType      String\n  size          Int\n  checksum      String?\n  changeReason  String?\n  status        FileAssetVersionStatus @default(ACTIVE)\n  createdById   String?\n  createdAt     DateTime               @default(now())\n\n  fileAsset  FileAsset  @relation(\"FileAssetVersions\", fields: [fileAssetId], references: [id], onDelete: Cascade)\n  currentFor FileAsset? @relation(\"FileAssetCurrentVersion\")\n  createdBy  User?      @relation(\"FileAssetVersionCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@unique([fileAssetId, versionNumber])\n  @@index([fileAssetId, status])\n}\n\n/// Job asynchrone de génération document (PDF / Excel / CSV) — traité par @repo/workers.\nmodel ReportGenerationJob {\n  id            String             @id @default(uuid())\n  templateKey   String\n  format        ReportOutputFormat\n  period        String\n  periodStart   DateTime\n  periodEnd     DateTime\n  periodLabel   String\n  title         String\n  summary       String?\n  status        ReportJobStatus    @default(PENDING)\n  progress      Int                @default(0)\n  errorMessage  String?\n  renderToken   String             @unique @default(uuid())\n  parameters    Json               @default(\"{}\")\n  fileAssetId   String?\n  requestedById String\n  createdAt     DateTime           @default(now())\n  updatedAt     DateTime           @updatedAt\n  completedAt   DateTime?\n\n  requestedBy User       @relation(\"ReportJobsRequested\", fields: [requestedById], references: [id])\n  fileAsset   FileAsset? @relation(fields: [fileAssetId], references: [id], onDelete: SetNull)\n\n  @@index([status, createdAt])\n  @@index([requestedById])\n  @@index([templateKey])\n}\n\nenum AiRunStatus {\n  PENDING\n  RUNNING\n  SUCCEEDED\n  FAILED\n}\n\nenum AiArtifactStatus {\n  PROPOSED\n  APPROVED\n  APPLIED\n  REJECTED\n}\n\n/// Exécution d'une tâche IA (génération de programme, déroulé, preuves Qualiopi...).\n/// Le modèle ne touche jamais la base directement : il produit un ou plusieurs\n/// AiArtifact que la fonction déterministe `apply*` correspondante valide et applique\n/// après revue humaine — jamais d'écriture directe par le LLM (GSMS-AI-01).\nmodel AiRun {\n  id               String      @id @default(uuid())\n  useCase          String\n  status           AiRunStatus @default(PENDING)\n  provider         String\n  model            String\n  inputSummary     Json        @default(\"{}\")\n  promptTokens     Int?\n  completionTokens Int?\n  costCents        Int?\n  errorMessage     String?\n  requestedById    String\n  createdAt        DateTime    @default(now())\n  updatedAt        DateTime    @updatedAt\n  completedAt      DateTime?\n\n  requestedBy User         @relation(\"AiRunsRequested\", fields: [requestedById], references: [id])\n  artifacts   AiArtifact[]\n\n  @@index([status, createdAt])\n  @@index([useCase])\n  @@index([requestedById])\n}\n\n/// Sortie structurée proposée par un AiRun. Reste à l'état PROPOSED tant qu'un humain\n/// ne l'a pas revue (reviewedById/reviewedAt) ; l'application effective (appliedAt) est\n/// faite par du code déterministe, jamais par le modèle lui-même.\nmodel AiArtifact {\n  id               String           @id @default(uuid())\n  runId            String\n  status           AiArtifactStatus @default(PROPOSED)\n  payload          Json\n  citations        Json             @default(\"[]\")\n  targetEntityType String?\n  targetEntityId   String?\n  reviewedById     String?\n  reviewedAt       DateTime?\n  appliedAt        DateTime?\n  createdAt        DateTime         @default(now())\n\n  run        AiRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n  reviewedBy User? @relation(\"AiArtifactReviewed\", fields: [reviewedById], references: [id], onDelete: SetNull)\n\n  @@index([runId])\n  @@index([status])\n  @@index([targetEntityType, targetEntityId])\n}\n\nenum AgentMessageRole {\n  USER\n  ASSISTANT\n}\n\n/// Fil de discussion agent attaché à un enregistrement (ex. un FundingCase). Une\n/// conversation par entité. La transcription seule vit ici — toute proposition\n/// d'écriture faite pendant la conversation reste un AiRun/AiArtifact séparé\n/// (GSMS-AI-01) : ce modèle ne porte aucun statut ni cycle de vie.\nmodel AgentConversation {\n  id               String   @id @default(uuid())\n  targetEntityType String\n  targetEntityId   String\n  createdAt        DateTime @default(now())\n\n  messages AgentMessage[]\n\n  @@unique([targetEntityType, targetEntityId])\n}\n\nmodel AgentMessage {\n  id             String           @id @default(uuid())\n  conversationId String\n  role           AgentMessageRole\n  content        String\n  createdAt      DateTime         @default(now())\n\n  conversation AgentConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId, createdAt])\n}\n\n/// Planification automatique des rapports (quotidien, mensuel, trimestriel).\nmodel ReportGenerationSchedule {\n  id          String                  @id @default(uuid())\n  templateKey String\n  format      ReportOutputFormat      @default(PDF)\n  frequency   ReportScheduleFrequency\n  title       String\n  summary     String?\n  parameters  Json                    @default(\"{}\")\n  enabled     Boolean                 @default(true)\n  lastRunAt   DateTime?\n  nextRunAt   DateTime?\n  createdById String?\n  createdAt   DateTime                @default(now())\n  updatedAt   DateTime                @updatedAt\n\n  @@index([enabled, nextRunAt])\n  @@index([frequency])\n}\n\nmodel UserBusinessRole {\n  id        String            @id @default(uuid())\n  userId    String\n  label     UserBusinessLabel\n  isPrimary Boolean           @default(false)\n  createdAt DateTime          @default(now())\n  updatedAt DateTime          @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, label])\n  @@index([label])\n  @@index([userId, isPrimary])\n}\n\nmodel CollaborateurProfile {\n  id                    String                 @id @default(uuid())\n  userId                String                 @unique\n  employeeCode          String?                @unique\n  companyId             String?\n  schoolInternalService SchoolInternalService?\n  managerUserId         String?\n  hireDate              DateTime?\n  endDate               DateTime?\n  contractType          String?\n  workTimeType          String?\n  qualification         String?\n  jobFunction           String?\n  carteProNumber        String?\n  carteProExpiry        DateTime?\n  socialSecurityNumber  String?\n  cniNumber             String?\n  residencePermitNumber String?\n  residencePermitExpiry DateTime?\n  birthDate             DateTime?\n  birthPlace            String?\n  nationality           String?\n  address               String?\n  city                  String?\n  postalCode            String?\n  country               String?\n  isSchedulable         Boolean                @default(true)\n  metadata              Json?                  @default(\"{}\")\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n\n  user    User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  manager User? @relation(\"CollaborateurManager\", fields: [managerUserId], references: [id], onDelete: SetNull)\n\n  @@index([companyId])\n  @@index([schoolInternalService])\n  @@index([managerUserId])\n}\n\nmodel FormateurProfile {\n  id                    String                 @id @default(uuid())\n  userId                String                 @unique\n  companyId             String?\n  /// Équipe interne rattachée (formateurs salariés / pool maison).\n  schoolInternalService SchoolInternalService?\n  trainingCenterId      String?\n  /// Première spécialité (doublon de confort avec `specialties[0]`).\n  speciality            String?\n  /**\n   * Domaines dispensés au catalogue (JSON string[]): SST, TFPAPS, SSIAP, etc.\n   */\n  specialties           Json                   @default(\"[]\")\n  pedagogicalReferences Json?                  @default(\"[]\")\n  certifications        Json?                  @default(\"[]\")\n  yearsOfExperience     Int?\n  hourlyRate            Float?\n  isInternal            Boolean                @default(true)\n  availability          Json?                  @default(\"{}\")\n  metadata              Json?                  @default(\"{}\")\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([companyId])\n  @@index([schoolInternalService])\n  @@index([trainingCenterId])\n  @@index([speciality])\n}\n\nmodel UserRole {\n  id              String               @id @default(uuid())\n  slug            String               @unique\n  name            String               @unique\n  description     String?\n  isTrashed       Boolean              @default(false)\n  createdByUserId String?\n  createdAt       DateTime             @default(now())\n  isProtected     Boolean              @default(false)\n  isDefault       Boolean              @default(false)\n  users           User[]\n  permissions     UserRolePermission[]\n}\n\nmodel UserPermission {\n  id              String               @id @default(uuid())\n  slug            String               @unique\n  name            String\n  description     String?\n  createdByUserId String?\n  createdAt       DateTime             @default(now())\n  roles           UserRolePermission[]\n}\n\nmodel UserRolePermission {\n  id           String   @id @default(uuid())\n  roleId       String\n  permissionId String\n  assignedAt   DateTime @default(now())\n\n  role       UserRole       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission UserPermission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@unique([roleId, permissionId])\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId], name: \"provider_providerAccountId\")\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nmodel SystemLog {\n  id          String   @id @default(uuid())\n  userId      String\n  createdAt   DateTime @default(now())\n  entityId    String?\n  entityType  String?\n  event       String?\n  description String?\n  ipAddress   String?\n  meta        String?\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n}\n\nmodel SystemSetting {\n  id                String  @id @default(uuid())\n  name              String  @default(\"My Company\")\n  logo              String?\n  active            Boolean @default(true)\n  address           String?\n  companyCity       String?\n  companyPostalCode String?\n  /// Identifiant légal entreprise (école / organisme).\n  siret             String?\n  /// Agrément CNAPS ou équivalent, si applicable.\n  cnaps             String?\n  /// Représentant / responsable légal affiché sur documents et profil école.\n  directorFullName  String?\n  /// Photo / avatar dirigeant (URL publique, preset `/compagnie-avatars/...` ou fichier uploadé).\n  directorAvatar    String?\n  industry          String?\n  companyType       String?\n  companySize       String?\n  companyRegion     String?\n\n  /// Numéro Déclaration Activité (NDA) et informations réglementaires formation.\n  ndaNumber              String?\n  ndaSpecialty           String?   @db.Text\n  ndaDeclaredAt          DateTime?\n  ndaRegion              String?\n  ndaTrainingActions     String?   @db.Text\n  qualiopiCertifications String?   @db.Text\n\n  /// Registre national des entreprises / données publiques INPI–INSEE (référence).\n  siren                     String?\n  establishmentNic          String?\n  vatIntracommunityNumber   String?\n  eoriNumber                String?\n  nafApeCode                String?\n  naf2025Code               String?\n  mainActivityDescription   String?\n  legalFormDetailed         String?   @db.Text\n  companyCreationDate       DateTime?\n  establishmentCreationDate DateTime?\n  inseeRegistrationDate     DateTime?\n  rneExtractDate            DateTime?\n  employeeSituationNote     String?   @db.Text\n  companySizeCategoryNote   String?   @db.Text\n  directorRole              String?\n  collectiveAgreementNote   String?   @db.Text\n  inpiCompanySummary        String?   @db.Text\n\n  /// Capital social (€), mention réglementaire.\n  shareCapitalEuros    Int?\n  /// Ex. greffe du tribunal de commerce (ville).\n  rcsRegistryCity      String?\n  agreementAdef        String?\n  agreementQualianor   String?\n  agreementQualiopiRef String?\n  agreementSsiap       String?\n\n  websiteURL              String?\n  supportEmail            String?\n  supportPhone            String?\n  /// WF-40 — référent handicap (P0 texte, pas de rôle dédié).\n  disabilityReferentName  String?\n  disabilityReferentEmail String?\n  disabilityReferentPhone String?\n  language                String  @default(\"en\")\n  timezone                String  @default(\"UTC\")\n  currency                String  @default(\"USD\")\n  currencyFormat          String  @default(\"$ {value}\")\n\n  socialFacebook  String?\n  socialTwitter   String?\n  socialInstagram String?\n  socialLinkedIn  String?\n  socialPinterest String?\n  socialYoutube   String?\n\n  notifyStockEmail               Boolean  @default(true)\n  notifyStockWeb                 Boolean  @default(true)\n  notifyStockThreshold           Int      @default(10)\n  notifyStockRoleIds             String[]\n  notifyNewOrderEmail            Boolean  @default(true)\n  notifyNewOrderWeb              Boolean  @default(true)\n  notifyNewOrderRoleIds          String[]\n  notifyOrderStatusUpdateEmail   Boolean  @default(true)\n  notifyOrderStatusUpdateWeb     Boolean  @default(true)\n  notifyOrderStatusUpdateRoleIds String[]\n  notifyPaymentFailureEmail      Boolean  @default(true)\n  notifyPaymentFailureWeb        Boolean  @default(true)\n  notifyPaymentFailureRoleIds    String[]\n  notifySystemErrorFailureEmail  Boolean  @default(true)\n  notifySystemErrorWeb           Boolean  @default(true)\n  notifySystemErrorRoleIds       String[]\n\n  /// Fiches du dossier administratif de l’école (références, dates, id de pièce jointe `FileAsset`).\n  administrativeDossier Json? @default(\"{}\")\n}\n\nmodel ClientSite {\n  id         String      @id @default(uuid())\n  name       String\n  code       String?     @unique\n  address    String?\n  city       String?\n  country    String?\n  isActive   Boolean     @default(true)\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n  equipments Equipment[]\n  rhTeams    RhTeam[]\n\n  @@index([name])\n}\n\nenum RhOrgUnitType {\n  DIRECTION\n  SERVICE\n  POLE\n  CAMPUS\n}\n\nenum RhTeamType {\n  PEDAGOGICAL\n  TRAINER_POOL\n  HR_ADMIN\n  DIRECTION\n  QUALITY\n  ADMIN\n}\n\nenum RhTeamSector {\n  HEADQUARTERS\n  CAMPUS\n  EXTERNAL\n}\n\n/// Cycle de vie d'une équipe liée à une session catalogue.\nenum RhTeamLifecycleStatus {\n  ACTIVE\n  POST_EXAM\n  ARCHIVED\n}\n\n/// Unité organisationnelle RH (direction, pôle, campus…)\nmodel RhOrgUnit {\n  id         String        @id @default(uuid())\n  name       String\n  type       RhOrgUnitType @default(SERVICE)\n  parentId   String?\n  managerId  String?\n  positionId String?\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n\n  parent   RhOrgUnit?  @relation(\"RhOrgUnitTree\", fields: [parentId], references: [id], onDelete: SetNull)\n  children RhOrgUnit[] @relation(\"RhOrgUnitTree\")\n  manager  User?       @relation(\"RhOrgUnitManager\", fields: [managerId], references: [id], onDelete: SetNull)\n  position RhPosition? @relation(fields: [positionId], references: [id], onDelete: SetNull)\n  teams    RhTeam[]\n\n  @@index([parentId])\n  @@index([managerId])\n  @@index([positionId])\n}\n\n/// Équipe opérationnelle RH (pôles pédagogiques, formateurs, qualité…)\nmodel RhTeam {\n  id                 String                @id @default(uuid())\n  name               String\n  description        String?\n  type               RhTeamType            @default(PEDAGOGICAL)\n  sector             RhTeamSector          @default(CAMPUS)\n  image              String?\n  siteId             String?\n  orgUnitId          String?\n  leaderId           String?\n  /// Équipe auto-provisionnée pour une session formation (1:1).\n  formationSessionId String?               @unique\n  lifecycleStatus    RhTeamLifecycleStatus @default(ACTIVE)\n  lifecycleClosedAt  DateTime?\n  createdAt          DateTime              @default(now())\n  updatedAt          DateTime              @updatedAt\n\n  site              ClientSite?        @relation(fields: [siteId], references: [id], onDelete: SetNull)\n  orgUnit           RhOrgUnit?         @relation(fields: [orgUnitId], references: [id], onDelete: SetNull)\n  leader            User?              @relation(\"RhTeamLeader\", fields: [leaderId], references: [id], onDelete: SetNull)\n  formationSession  FormationSession?  @relation(fields: [formationSessionId], references: [id], onDelete: SetNull)\n  members           RhTeamMember[]\n  chatConversations ChatConversation[]\n\n  @@index([siteId])\n  @@index([orgUnitId])\n  @@index([leaderId])\n  @@index([name])\n  @@index([lifecycleStatus])\n}\n\nmodel RhTeamMember {\n  id        String   @id @default(uuid())\n  teamId    String\n  userId    String\n  createdAt DateTime @default(now())\n\n  team RhTeam @relation(fields: [teamId], references: [id], onDelete: Cascade)\n  user User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([teamId, userId])\n  @@index([userId])\n}\n\nenum RhAbsenceType {\n  CONGE_PAYE\n  MALADIE\n  RTT\n  AUTRE\n}\n\nenum RhAbsenceStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// Demande d'absence / congé collaborateur\nmodel RhAbsence {\n  id            String          @id @default(uuid())\n  userId        String\n  type          RhAbsenceType\n  status        RhAbsenceStatus @default(PENDING)\n  startDate     DateTime        @db.Date\n  endDate       DateTime        @db.Date\n  reason        String?         @db.Text\n  validatedById String?\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n\n  user        User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  validatedBy User? @relation(\"RhAbsenceValidatedBy\", fields: [validatedById], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([status])\n  @@index([startDate])\n}\n\n/// Référentiel postes / fonctions métier école\nmodel RhPosition {\n  id                    String                 @id @default(uuid())\n  label                 String\n  code                  String?                @unique\n  schoolInternalService SchoolInternalService?\n  sortOrder             Int                    @default(0)\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n\n  users    User[]\n  orgUnits RhOrgUnit[]\n\n  @@index([sortOrder])\n  @@index([schoolInternalService, sortOrder])\n}\n\n/// Référentiel qualifications par pôle interne (CFA).\nmodel RhQualification {\n  id                    String                @id @default(uuid())\n  label                 String\n  code                  String                @unique\n  schoolInternalService SchoolInternalService\n  sortOrder             Int                   @default(0)\n  createdAt             DateTime              @default(now())\n  updatedAt             DateTime              @updatedAt\n\n  @@index([schoolInternalService, sortOrder])\n}\n\nmodel Equipment {\n  id                  String                   @id @default(uuid())\n  serialNumber        String                   @unique\n  label               String\n  type                String?\n  status              EquipmentStatus          @default(AVAILABLE)\n  assignedSiteId      String?\n  assignedSite        ClientSite?              @relation(fields: [assignedSiteId], references: [id], onDelete: SetNull)\n  metadata            Json?                    @default(\"{}\")\n  avatar              String?\n  createdAt           DateTime                 @default(now())\n  updatedAt           DateTime                 @updatedAt\n  maintenanceItems    EquipmentMaintenance[]\n  stockMovements      StockMovement[]\n  sessions            TrainingSession[]\n  roomFixedAssignment VenueRoomFixedEquipment?\n  qualityIncidents    QualityIncident[]\n\n  @@index([status])\n  @@index([type])\n  @@index([assignedSiteId])\n}\n\nmodel EquipmentMaintenance {\n  id            String                     @id @default(uuid())\n  equipmentId   String\n  status        EquipmentMaintenanceStatus @default(SCHEDULED)\n  title         String?\n  notes         String?\n  scheduledDate DateTime?\n  completedDate DateTime?\n  /// Coût intervention / pièces (€) — charge budget EQUIPEMENT.\n  costAmount    Decimal?                   @db.Decimal(12, 2)\n  createdAt     DateTime                   @default(now())\n  updatedAt     DateTime                   @updatedAt\n  equipment     Equipment                  @relation(fields: [equipmentId], references: [id], onDelete: Cascade)\n\n  @@index([equipmentId])\n  @@index([status])\n  @@index([scheduledDate])\n}\n\nmodel StockMovement {\n  id           String            @id @default(uuid())\n  equipmentId  String\n  type         StockMovementType\n  quantity     Int\n  movementDate DateTime          @default(now())\n  notes        String?\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n  equipment    Equipment         @relation(fields: [equipmentId], references: [id], onDelete: Cascade)\n\n  @@index([equipmentId])\n  @@index([type])\n  @@index([movementDate])\n}\n\n// --- CRM: catalogue formations (fiches vitrine + sessions commerciales ; aligné sheets Formations CRM / landing) ---\n// Distinct du LMS `TrainingSession` (instances liées à `Course`).\n\nenum FormationLifecycleStatus {\n  DRAFT\n  ACTIVE\n  ARCHIVED\n}\n\nenum FormationTrack {\n  surete\n  incendie\n  habilitation\n  sst\n  entreprise\n  autres\n}\n\nenum FormationParcoursSpecialite {\n  INITIAL\n  MAC\n  RAN\n  AUTRE\n}\n\nenum FormationDeliveryMode {\n  PRESENTIEL\n  DISTANCIEL\n  MIXTE\n  ENTREPRISE_SUR_SITE\n}\n\n/// Sessions vitrine CRM. `sessionKind` est **dérivé du parcours** de la formation :\n/// parcours Initial â `WITH_EXAM` (examen en fin de parcours) ; MAC / RAN / Autre â `INITIAL`.\n/// Valeur `OTHER` réservée aux cas exceptionnels. Le CRM ne propose pas un interrupteur « avec/sans examen » séparé.\nenum FormationVitrineSessionKind {\n  INITIAL\n  WITH_EXAM\n  OTHER\n}\n\nmodel Formation {\n  id          String  @id @default(uuid())\n  slug        String  @unique\n  name        String\n  /// Résumé carte liste / SEO (catalogue vitrine).\n  description String? @db.Text\n\n  track              FormationTrack\n  tag                String\n  duration           String                      @db.Text\n  parcoursSpecialite FormationParcoursSpecialite @default(INITIAL)\n\n  status   FormationLifecycleStatus @default(DRAFT)\n  featured Boolean                  @default(false)\n\n  /// Sidebar : logo formation (URL ou clé média).\n  logoUrl          String? @db.Text\n  providerName     String?\n  providerEmail    String?\n  providerPhone    String?\n  providerAddress  String? @db.Text\n  /// Libellé rapide type « Dès le 04 Mai 2026 » (sidebar upload).\n  nextSessionLabel String?\n\n  cpfEligible       Boolean @default(false)\n  qualiopiCertified Boolean @default(false)\n  rncpUrl           String? @db.Text\n  rncpCode          String?\n\n  deliveryMode FormationDeliveryMode?\n\n  /// KPI vue d’ensemble (statistics1) — scalaires pour filtres / tri ; détails dans overviewMetrics si besoin.\n  hoursMin               Int?\n  hoursMax               Int?\n  traineesMin            Int?\n  traineesMax            Int?\n  priceFrom              Decimal? @db.Decimal(10, 2)\n  currency               String   @default(\"EUR\")\n  successRate            Decimal? @db.Decimal(5, 2)\n  clientSatisfactionRate Decimal? @db.Decimal(5, 2)\n\n  /// Bandeau Programme (statistics2).\n  unitsCount       Int?\n  volumeHoursLabel String?\n  theoryPercent    Int?\n  practicePercent  Int?\n\n  /// Bandeau Prérequis (statistics4).\n  minAgeLabel               String?\n  frenchLevel               String?\n  authorizationSummary      String?\n  criminalRecordRequirement String?\n\n  /// Carte « Présentation » (resent-order).\n  presentationTitle String?\n  longDescription   String? @db.Text\n\n  /// listes / tableaux riches (structure libre, consommée par les sheets CRM).\n  modules              Json @default(\"[]\")\n  outcomes             Json @default(\"[]\")\n  presentationBullets  Json @default(\"[]\")\n  programModules       Json @default(\"[]\")\n  prerequisitesTable   Json @default(\"[]\")\n  fundingBlocks        Json @default(\"[]\")\n  fundingChannels      Json @default(\"[]\")\n  overviewMetrics      Json @default(\"[]\")\n  certificationSteps   Json @default(\"[]\")\n  /// Résumés carte « Détails complémentaires » + métadonnées UI (axes, version commerciale…).\n  complementaryDetails Json @default(\"{}\")\n\n  /// Routage type sheet landing (`FORMATION_CATALOG_PROGRAM_BY_SLUG`) sérialisé en JSON.\n  catalogProgramConfig Json @default(\"{}\")\n\n  /// Pont optionnel vers un cours LMS (sync progression / TrainingSession).\n  courseId String? @unique\n  course   Course? @relation(fields: [courseId], references: [id], onDelete: SetNull)\n\n  sessions            FormationSession[]\n  portalAnnouncements PortalSessionAnnouncement[]\n  quizQuestionBanks   QuizQuestionBank[]\n\n  /// Offre catalogue CRM\n  catalogOffer FormationCatalogOffer?\n\n  /// Ligne catalogue finance (prestations / tarifs devis), synchronisée depuis l’offre catalogue.\n  financeCatalogLine FinanceCatalogLine?\n\n  candidatures     Candidature[]\n  attestations     FormationAttestation[]\n  /// Demandes de devis landing (Lead.source = Landing demande de devis).\n  quoteLeads       Lead[]                 @relation(\"LeadQuoteFormation\")\n  financeDevis     FinanceDevis[]\n  trainingRequests TrainingRequest[]\n  evidences        Evidence[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([track])\n  @@index([parcoursSpecialite])\n  @@index([featured])\n}\n\n/// Inclusion d'une fiche référence dans le catalogue école — pas de duplication métier, surcharges optionnelles.\nmodel FormationCatalogOffer {\n  id          String    @id @default(uuid())\n  formationId String    @unique\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  /// Visible catalogue / brouillon / suspendu (archivé). La ligne référence `Formation` n'est jamais supprimée.\n  catalogStatus FormationLifecycleStatus @default(ACTIVE)\n\n  priceFromOverride Decimal? @db.Decimal(10, 2)\n  currencyOverride  String?\n\n  /// Affichage catalogue : initial / MAC / RANâ¦ si null, reprend `Formation.parcoursSpecialite`.\n  parcoursSpecialiteOverride FormationParcoursSpecialite?\n\n  fundingBlocksOverride      Json?\n  fundingChannelsOverride    Json?\n  prerequisitesTableOverride Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([catalogStatus])\n}\n\n/// Volet affiché sur la section #trainers du landing.\nenum LandingTeamVolet {\n  direction\n  formateur\n  pedagogique\n  rh\n}\n\n/// Membre de l'équipe publiée sur le landing (#trainers) — lié à un compte RH / formateur.\nmodel LandingTeamOffer {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  volet LandingTeamVolet\n\n  catalogStatus FormationLifecycleStatus @default(ACTIVE)\n\n  sortOrder Int @default(0)\n\n  titleOverride               String?\n  certificationsLabelOverride String? @db.Text\n  bioOverride                 String? @db.Text\n  statAOverride               Int?\n  statBOverride               Int?\n  ratingOverride              Float?\n  linkedinUrl                 String?\n  websiteUrl                  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([catalogStatus, volet, sortOrder])\n}\n\n/// Salle ou espace pédagogique réservable pour les sessions catalogue CRM (libellés métier : « Salle Aurore », etc.).\nmodel FormationVenueRoom {\n  id             String                    @id @default(uuid())\n  name           String\n  shortCode      String?                   @unique\n  capacity       Int?\n  floorLabel     String?\n  /// Visuel vitrine (URL relative Next `/media/...`).\n  imageUrl       String?\n  isActive       Boolean                   @default(true)\n  sortOrder      Int                       @default(0)\n  sessions       FormationSession[]\n  examSessions   FormationSession[]        @relation(\"FormationSessionExamRoom\")\n  formationExams FormationExam[]           @relation(\"FormationExamVenueRoom\")\n  bookings       VenueRoomBooking[]\n  fixedEquipment VenueRoomFixedEquipment[]\n  createdAt      DateTime                  @default(now())\n  updatedAt      DateTime                  @updatedAt\n\n  @@index([isActive])\n  @@index([sortOrder])\n}\n\n/// Mobilier / matériel permanent installé dans une salle (chaises, vidéoprojecteur…).\n/// Distinct des `FormationSession.reservedEquipmentIds` (réservation ponctuelle session).\nmodel VenueRoomFixedEquipment {\n  id          String             @id @default(uuid())\n  venueRoomId String\n  venueRoom   FormationVenueRoom @relation(fields: [venueRoomId], references: [id], onDelete: Cascade)\n  equipmentId String             @unique\n  equipment   Equipment          @relation(fields: [equipmentId], references: [id], onDelete: Cascade)\n  quantity    Int                @default(1)\n  installedAt DateTime?\n  notes       String?            @db.Text\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n\n  @@index([venueRoomId])\n}\n\nenum VenueRoomBookingKind {\n  STAFF_MEETING\n  INFO_MEETING\n  OTHER\n}\n\nenum VenueRoomBookingStatus {\n  ACTIVE\n  CANCELLED\n}\n\n/// Réservation ponctuelle de salle (réunion staff, réunion info, etc.) — hors session catalogue.\nmodel VenueRoomBooking {\n  id              String                 @id @default(uuid())\n  venueRoomId     String\n  venueRoom       FormationVenueRoom     @relation(fields: [venueRoomId], references: [id], onDelete: Cascade)\n  title           String\n  kind            VenueRoomBookingKind   @default(STAFF_MEETING)\n  status          VenueRoomBookingStatus @default(ACTIVE)\n  startAt         DateTime\n  endAt           DateTime\n  notes           String?                @db.Text\n  organizerUserId String?\n  organizer       User?                  @relation(\"VenueRoomBookingOrganizer\", fields: [organizerUserId], references: [id], onDelete: SetNull)\n  createdAt       DateTime               @default(now())\n  updatedAt       DateTime               @updatedAt\n\n  @@index([venueRoomId])\n  @@index([startAt])\n  @@index([endAt])\n  @@index([status])\n}\n\nmodel FormationSession {\n  id          String    @id @default(uuid())\n  formationId String\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  startDate DateTime?\n  endDate   DateTime?\n\n  /// Clôture des inscriptions (horodatage).\n  registrationClosesAt     DateTime?\n  /// Date / heure d’examen prévue (optionnel).\n  examDate                 DateTime?\n  /// Salle d’examen (PCS, plateau incendie…) si différente de la salle de cours.\n  examVenueRoomId          String?\n  examVenueRoom            FormationVenueRoom? @relation(\"FormationSessionExamRoom\", fields: [examVenueRoomId], references: [id], onDelete: SetNull)\n  /// Matériel mobile réservé pour le jour d’examen (magnétomètre, fumigènes…).\n  examReservedEquipmentIds Json                @default(\"[]\")\n\n  /// Effectif cible pour cette session (distinct de la fourchette « fiche formation »).\n  traineesMin Int?\n  traineesMax Int?\n\n  /// Formateur référent (compte rôle formateur).\n  trainerUserId String?\n  trainer       User?   @relation(\"FormationSessionTrainer\", fields: [trainerUserId], references: [id], onDelete: SetNull)\n\n  /// Référent pédagogique modérateur du chat de session.\n  moderatorUserId String?\n  moderator       User?   @relation(\"FormationSessionModerator\", fields: [moderatorUserId], references: [id], onDelete: SetNull)\n\n  /// Groupe chat lié (formateur + élèves + modérateur) — relation inverse.\n  chatConversation ChatConversation?\n\n  /// Salle allouée (disponibilité = pas de autre session même salle sur dates qui se chevauchent).\n  venueRoomId String?\n  venueRoom   FormationVenueRoom? @relation(fields: [venueRoomId], references: [id], onDelete: SetNull)\n\n  /// Identifiants `Equipment` réservés pour la session (JSON : tableau d’UUID).\n  reservedEquipmentIds Json @default(\"[]\")\n\n  /// Libellé affiché (ex. « 04 Mai au 12 Juin 2026 ») tant que les dates ne sont pas renseignées partout.\n  dateDisplayLabel String                      @db.Text\n  location         String\n  sessionKind      FormationVitrineSessionKind @default(INITIAL)\n\n  /// SD-06 session readiness (WF-10)\n  readinessStatus SessionReadinessStatus @default(DRAFT)\n\n  venueBrandPrefix String? @db.Text\n  sessionSubtitle  String?\n\n  sortOrder      Int     @default(0)\n  bookingEnabled Boolean @default(false)\n  bookingUrl     String? @db.Text\n\n  participants        FormationSessionParticipant[]\n  suiviDays           FormationSessionDay[]\n  attestations        FormationAttestation[]\n  formationExam       FormationExam?\n  portalAnnouncements PortalSessionAnnouncement[]\n  rhTeam              RhTeam?\n  satisfactionSurveys SatisfactionSurvey[]\n  fundingCases        FundingCase[]\n  evidences           Evidence[]\n  readinessEvents     SessionReadinessEvent[]\n  conventions         FormationSessionConvention[]\n\n  candidaturesInterested   Candidature[]          @relation(\"CandidatureInterestedSession\")\n  financeDevisSessionLinks FinanceDevis[]         @relation(\"FinanceDevisLinkedSession\")\n  automationRuns           SessionAutomationRun[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([formationId])\n  @@index([startDate])\n  @@index([venueRoomId])\n  @@index([examVenueRoomId])\n  @@index([readinessStatus])\n}\n\nenum SessionAutomationStatus {\n  RUNNING\n  COMPLETED\n  CANCELLED\n  FAILED\n}\n\n/// Exécution circuit n8n (jalons J-15 → J+45) — suivi / annulation si session reportée.\nmodel SessionAutomationRun {\n  id             String                  @id @default(uuid())\n  sessionId      String\n  session        FormationSession        @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  participantId  String?\n  candidatureId  String?\n  circuitKey     String                  @default(\"default\")\n  n8nExecutionId String?\n  status         SessionAutomationStatus @default(RUNNING)\n  milestones     Json                    @default(\"[]\")\n  metadata       Json                    @default(\"{}\")\n  startedAt      DateTime                @default(now())\n  completedAt    DateTime?\n  cancelledAt    DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([sessionId])\n  @@index([status])\n  @@index([n8nExecutionId])\n}\n\n/// Annonce portail candidat â cible une session ou toute la formation (sessionId null).\nmodel PortalSessionAnnouncement {\n  id          String            @id @default(uuid())\n  formationId String\n  formation   Formation         @relation(fields: [formationId], references: [id], onDelete: Cascade)\n  sessionId   String?\n  session     FormationSession? @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  title       String\n  content     String            @db.Text\n  publishedAt DateTime          @default(now())\n  isPublished Boolean           @default(true)\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  @@index([formationId])\n  @@index([sessionId])\n  @@index([publishedAt])\n}\n\n/// Dossier d’entrée CRM\nmodel Candidature {\n  id String @id @default(uuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  formationId String?\n  formation   Formation? @relation(fields: [formationId], references: [id], onDelete: SetNull)\n\n  /// Session précise visée depuis le landing (optionnel ; doit appartenir à `formationId` lorsque les deux sont renseignés).\n  interestedSessionId String?\n  interestedSession   FormationSession? @relation(\"CandidatureInterestedSession\", fields: [interestedSessionId], references: [id], onDelete: SetNull)\n\n  leadId String? @unique\n  lead   Lead?   @relation(fields: [leadId], references: [id], onDelete: SetNull)\n\n  source CandidatureSource @default(MANUAL)\n  status CandidatureStatus @default(DRAFT)\n\n  cnapsSubmittedAt  DateTime?\n  cnapsReference    String?\n  cnapsDecisionAt   DateTime?\n  /// Réponse PN/CNAPS lorsque suivie manuellement (null = encore en cours).\n  cnapsPrefavorable Boolean?\n\n  validatedAt DateTime?\n  completedAt DateTime?\n  archivedAt  DateTime?\n\n  notes    String? @db.Text\n  metadata Json    @default(\"{}\")\n\n  documentsCompleteAt DateTime?\n  complianceDossiers  ComplianceDossier[]\n  sessionEnrollments  FormationSessionParticipant[]\n  attestations        FormationAttestation[]\n  financeDevis        FinanceDevis[]\n  assessments         CandidatureAssessment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([formationId])\n  @@index([status])\n  @@index([interestedSessionId])\n}\n\n/// WF-02 / WF-03 — analyse du besoin + positionnement (pattern SatisfactionSurvey).\nenum CandidatureAssessmentKind {\n  NEEDS_ANALYSIS\n  POSITIONING\n}\n\nenum CandidatureAssessmentStatus {\n  PENDING\n  SENT\n  COMPLETED\n}\n\n/// WF-04 — suivi accessibilité / aménagement côté candidature.\nenum AdaptationStatus {\n  NO_ADAPTATION_REQUIRED\n  ADAPTATION_PENDING\n  ADAPTATION_APPROVED\n  ADAPTATION_IMPLEMENTED\n}\n\nmodel CandidatureAssessment {\n  id                   String                      @id @default(uuid())\n  candidatureId        String\n  kind                 CandidatureAssessmentKind\n  status               CandidatureAssessmentStatus @default(PENDING)\n  sentAt               DateTime?\n  completedAt          DateTime?\n  /// Réponses questionnaire (Json libre).\n  answers              Json?\n  /// WF-03 — niveau constaté (libre).\n  level                String?\n  /// WF-03 — OK / PARTIAL / MISSING (ou texte libre).\n  prerequisitesStatus  String?\n  /// Signal adaptation (lien WF-04 organisme, info staff).\n  adaptationRequired   Boolean?\n  /// WF-04 — cycle aménagement (renseigné surtout sur NEEDS_ANALYSIS).\n  adaptationStatus     AdaptationStatus?\n  adaptationNotifiedAt DateTime?\n  adaptationNotes      String?                     @db.Text\n\n  candidature Candidature @relation(fields: [candidatureId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([candidatureId, kind])\n  @@index([candidatureId])\n  @@index([status])\n  @@index([adaptationRequired])\n  @@index([adaptationStatus])\n}\n\n/// Participation à une session vitrine CRM. `candidatureId` rattache au dossier validé lorsqu’existant.\nmodel FormationSessionParticipant {\n  id        String           @id @default(uuid())\n  sessionId String\n  session   FormationSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  candidatureId String?\n  candidature   Candidature? @relation(fields: [candidatureId], references: [id], onDelete: SetNull)\n\n  enrollmentStatus FormationSessionEnrollmentStatus @default(CONFIRMED)\n\n  examOutcome         FormationExamOutcome @default(PENDING)\n  examDate            DateTime?\n  certifiedAt         DateTime?\n  trainingCompletedAt DateTime?\n\n  /// Financeur / modalité de prise en charge (CPF, France Travail, OPCO…).\n  fundingMode      String?\n  fundingReference String?\n  fundingNotes     String? @db.Text\n\n  /// WF-14 — rappel J-5 préparation pédagogique déjà envoyé.\n  j5PrepReminderSentAt DateTime?\n\n  emargements         FormationSessionEmargement[]\n  satisfactionSurveys SatisfactionSurvey[]\n  fundingCases        FundingCase[]\n  conventions         FormationSessionConvention[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([sessionId, userId])\n  @@index([userId])\n  @@index([j5PrepReminderSentAt])\n  @@index([candidatureId])\n  @@index([examOutcome])\n}\n\n/// Jour de formation dans le suivi quotidien CRM (dates dérivées de la session ou ajout manuel).\nmodel FormationSessionDay {\n  id        String           @id @default(uuid())\n  sessionId String\n  session   FormationSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  dayDate DateTime @db.Date\n\n  journalNotesMorning String? @db.Text\n  journalNotesEvening String? @db.Text\n\n  attendances FormationSessionEmargement[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([sessionId, dayDate])\n  @@index([sessionId])\n}\n\n/// Émargement nominatif par stagiaire et créneau (matin / soir).\nmodel FormationSessionEmargement {\n  id            String                      @id @default(uuid())\n  dayId         String\n  day           FormationSessionDay         @relation(fields: [dayId], references: [id], onDelete: Cascade)\n  participantId String\n  participant   FormationSessionParticipant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n\n  slot   FormationSessionDaySlot\n  status FormationSessionEmargementStatus @default(PRESENT)\n\n  markedAt       DateTime?\n  markedByUserId String?\n  markedBy       User?     @relation(\"FormationSessionEmargementMarkedBy\", fields: [markedByUserId], references: [id], onDelete: SetNull)\n  notes          String?   @db.Text\n\n  /// WF-18 — null sauf si status = ABSENT.\n  justificationStatus      AbsenceJustificationStatus?\n  justificationRequestedAt DateTime?\n  justificationNote        String?                     @db.Text\n  justificationResolvedAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([dayId, participantId, slot])\n  @@index([participantId])\n  @@index([dayId])\n  @@index([justificationStatus])\n}\n\n/// WF-08 — convention de formation par participant (cycle GENERATED→…→ARCHIVED).\nmodel FormationSessionConvention {\n  id             String                  @id @default(uuid())\n  sessionId      String\n  participantId  String\n  status         SessionConventionStatus @default(GENERATED)\n  fileAssetId    String?\n  /// Token signé optionnel pour ouverture publique (VIEWED).\n  publicToken    String?                 @unique\n  sentAt         DateTime?\n  viewedAt       DateTime?\n  signedAt       DateTime?\n  lastReminderAt DateTime?\n  reminderCount  Int                     @default(0)\n  createdAt      DateTime                @default(now())\n  updatedAt      DateTime                @updatedAt\n\n  session     FormationSession            @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  participant FormationSessionParticipant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n  fileAsset   FileAsset?                  @relation(fields: [fileAssetId], references: [id], onDelete: SetNull)\n\n  @@unique([sessionId, participantId])\n  @@index([sessionId])\n  @@index([status])\n  @@index([sentAt])\n}\n\n/// Examen catalogue lié à une session `WITH_EXAM` (1:1).\nmodel FormationExam {\n  id        String           @id @default(uuid())\n  sessionId String           @unique\n  session   FormationSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  scheduledAt DateTime?\n  venueRoomId String?\n  venueRoom   FormationVenueRoom? @relation(\"FormationExamVenueRoom\", fields: [venueRoomId], references: [id], onDelete: SetNull)\n\n  status FormationExamStatus @default(PLANNED)\n\n  juryPresidentName String?\n  examinerName      String?\n  /// Membres du jury (JSON string[]).\n  juryMemberNames   Json    @default(\"[]\")\n  notes             String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([scheduledAt])\n  @@index([status])\n  @@index([venueRoomId])\n}\n\n/// Attestation / certification délivrée après parcours catalogue CRM (distinct du LMS `UserCertificate`).\nmodel FormationAttestation {\n  id String @id @default(uuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  candidatureId String?\n  candidature   Candidature? @relation(fields: [candidatureId], references: [id], onDelete: SetNull)\n\n  formationId String\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  sessionId String?\n  session   FormationSession? @relation(fields: [sessionId], references: [id], onDelete: SetNull)\n\n  title          String\n  certificateUrl String?   @db.Text\n  issueDate      DateTime  @default(now())\n  expiryDate     DateTime?\n  metadata       Json      @default(\"{}\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([candidatureId])\n  @@index([formationId])\n  @@index([sessionId])\n}\n\n// LMS Models\nmodel Course {\n  id          String  @id @default(uuid())\n  createdById String\n  title       String  @db.Text\n  description String? @db.Text\n  imageUrl    String? @db.Text\n  price       Float?\n  isPublished Boolean @default(false)\n\n  attachments Attachment[]\n  category    Category?    @relation(fields: [categoryId], references: [id])\n  categoryId  String?\n  chapters    Chapter[]\n  purchases   Purchase[]\n  createdBy   User         @relation(fields: [createdById], references: [id], onDelete: Cascade)\n\n  trainingSessions TrainingSession[]\n  enrollments      Enrollment[]\n  grades           Grade[]\n\n  certifications Certification[]\n  community      Community?\n  embeddings     CourseEmbedding[]\n  collections    Collection[]      @relation(\"CourseToCollection\")\n  leads          Lead[]\n  trailSteps     TrailStep[]\n\n  formationCatalog  Formation?\n  quizQuestionBanks QuizQuestionBank[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([categoryId])\n  @@index([createdById])\n}\n\nmodel Category {\n  id      String   @id @default(uuid())\n  name    String   @unique\n  courses Course[]\n}\n\nmodel Attachment {\n  id   String @id @default(uuid())\n  name String\n  url  String @db.Text\n\n  course   Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  courseId String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([courseId])\n}\n\nmodel Chapter {\n  id          String  @id @default(uuid())\n  title       String\n  description String? @db.Text\n  videoUrl    String? @db.Text\n  position    Int\n  isPublished Boolean @default(false)\n  isFree      Boolean @default(false)\n\n  reviewStatus         LmsContentReviewStatus @default(APPROVED)\n  submittedForReviewAt DateTime?\n  reviewedAt           DateTime?\n  reviewNote           String?                @db.Text\n  reviewedById         String?\n  reviewedBy           User?                  @relation(\"ChapterReviewer\", fields: [reviewedById], references: [id], onDelete: SetNull)\n\n  muxData       MuxData?\n  course        Course                 @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  courseId      String\n  userProgress  UserProgress[]\n  activities    Activity[]\n  quizBankItems QuizQuestionBankItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([courseId])\n  @@index([reviewStatus])\n}\n\nenum ActivityType {\n  VIDEO\n  DOCUMENT\n  DYNAMIC\n  ASSIGNMENT\n  QUIZ\n}\n\nenum ActivitySubType {\n  VIDEO_YOUTUBE\n  VIDEO_HOSTED\n  DOCUMENT_PDF\n  DYNAMIC_PAGE\n  DYNAMIC_MARKDOWN\n  QUIZ_MULTIPLE_CHOICE\n}\n\n/// Workflow brouillon â validation admin (optionnel via LMS_CONTENT_REVIEW_REQUIRED).\nenum LmsContentReviewStatus {\n  DRAFT\n  PENDING_REVIEW\n  APPROVED\n  REJECTED\n}\n\nmodel Activity {\n  id          String          @id @default(uuid())\n  name        String\n  type        ActivityType\n  subType     ActivitySubType\n  content     Json            @default(\"{}\")\n  details     Json?           @default(\"{}\")\n  isPublished Boolean         @default(false)\n  position    Int\n\n  reviewStatus         LmsContentReviewStatus @default(APPROVED)\n  submittedForReviewAt DateTime?\n  reviewedAt           DateTime?\n  reviewNote           String?                @db.Text\n  reviewedById         String?\n  reviewedBy           User?                  @relation(\"ActivityReviewer\", fields: [reviewedById], references: [id], onDelete: SetNull)\n\n  chapterId String\n  chapter   Chapter @relation(fields: [chapterId], references: [id], onDelete: Cascade)\n\n  assignment   Assignment?\n  embeddings   CourseEmbedding[]\n  quizAttempts QuizAttempt[]\n\n  lastModifiedById String?\n  lastModifiedBy   User?   @relation(\"ActivityModifier\", fields: [lastModifiedById], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([chapterId])\n  @@index([reviewStatus])\n}\n\nmodel MuxData {\n  id         String  @id @default(uuid())\n  assetId    String\n  playbackId String?\n\n  chapter   Chapter @relation(fields: [chapterId], references: [id], onDelete: Cascade)\n  chapterId String  @unique\n}\n\n/// Banque de questions QCM réutilisable (par formation ou cours LMS).\nmodel QuizQuestionBank {\n  id          String                 @id @default(uuid())\n  title       String\n  formationId String?\n  formation   Formation?             @relation(fields: [formationId], references: [id], onDelete: Cascade)\n  courseId    String?\n  course      Course?                @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  createdById String\n  createdBy   User                   @relation(\"QuizBankCreator\", fields: [createdById], references: [id], onDelete: Cascade)\n  items       QuizQuestionBankItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([formationId])\n  @@index([courseId])\n  @@index([createdById])\n}\n\nmodel QuizQuestionBankItem {\n  id           String           @id @default(uuid())\n  bankId       String\n  bank         QuizQuestionBank @relation(fields: [bankId], references: [id], onDelete: Cascade)\n  position     Int              @default(0)\n  prompt       String           @db.Text\n  /// Liste de réponses proposées (JSON string[]).\n  choices      Json             @default(\"[]\")\n  correctIndex Int              @default(0)\n  tags         String[]         @default([])\n  /// UV LMS (chapitre) — banque QCM par unité de valeur.\n  chapterId    String?\n  chapter      Chapter?         @relation(fields: [chapterId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([bankId])\n  @@index([chapterId])\n}\n\nmodel UserProgress {\n  id     String @id @default(uuid())\n  userId String\n\n  chapter     Chapter @relation(fields: [chapterId], references: [id], onDelete: Cascade)\n  chapterId   String\n  isCompleted Boolean @default(false)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, chapterId])\n  @@index([chapterId])\n}\n\n/// Tentative quiz portail candidat (correction serveur).\nmodel QuizAttempt {\n  id         String   @id @default(uuid())\n  userId     String\n  activityId String\n  answers    Json     @default(\"{}\")\n  score      Int\n  passed     Boolean\n  createdAt  DateTime @default(now())\n\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  activity Activity @relation(fields: [activityId], references: [id], onDelete: Cascade)\n\n  @@index([userId, activityId])\n  @@index([activityId])\n}\n\nmodel Purchase {\n  id     String @id @default(uuid())\n  userId String\n\n  course   Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  courseId String\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, courseId])\n  @@index([courseId])\n}\n\nmodel StripeCustomer {\n  id               String @id @default(uuid())\n  userId           String @unique\n  stripeCustomerId String @unique\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel TrainingSession {\n  id           String   @id @default(uuid())\n  title        String\n  description  String?  @db.Text\n  startDate    DateTime\n  endDate      DateTime\n  location     String? // Salle de classe ou URL visioconférence\n  instructorId String?\n  instructor   User?    @relation(\"Instructor\", fields: [instructorId], references: [id])\n\n  courseId String\n  course   Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  enrollments Enrollment[]\n  attendances Attendance[]\n  equipments  Equipment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([courseId])\n  @@index([instructorId])\n}\n\nmodel Enrollment {\n  id        String           @id @default(uuid())\n  userId    String\n  courseId  String\n  sessionId String?\n  status    EnrollmentStatus @default(PENDING)\n\n  documents Json?   @default(\"[]\") // Liste d'URLs pour le dossier d'admission\n  notes     String? @db.Text\n\n  user    User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  course  Course           @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  session TrainingSession? @relation(fields: [sessionId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, courseId, sessionId])\n  @@index([userId])\n  @@index([courseId])\n  @@index([sessionId])\n}\n\nmodel Attendance {\n  id        String           @id @default(uuid())\n  userId    String\n  sessionId String\n  date      DateTime         @default(now())\n  status    AttendanceStatus @default(PRESENT)\n\n  user    User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  session TrainingSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, sessionId, date])\n  @@index([userId])\n  @@index([sessionId])\n}\n\nmodel Grade {\n  id        String  @id @default(uuid())\n  userId    String\n  courseId  String\n  chapterId String?\n  value     Float // La note (ex: 15.5)\n  weight    Float   @default(1.0) // Coefficient\n  comment   String? @db.Text\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([courseId])\n}\n\nenum LeadStatus {\n  NEW\n  CONTACTED\n  QUALIFIED\n  CONVERTED\n  LOST\n}\n\n/// Cycle commercial d'un devis (module Finance).\nenum FinanceDevisStatus {\n  DRAFT\n  SENT\n  VIEWED\n  ACCEPTED\n  REJECTED\n  EXPIRED\n}\n\n/// Cycle e-facture (émission Factur-X / PDP) — distinct du statut commercial.\nenum FinanceEinvoiceStatus {\n  NOT_READY\n  READY\n  GENERATED\n  QUEUED\n  SENT\n  ACCEPTED_BY_PDP\n  REJECTED_BY_PDP\n  FAILED\n}\n\nmodel Lead {\n  id        String     @id @default(uuid())\n  firstName String\n  lastName  String\n  email     String\n  phone     String?\n  source    String? // ex: \"Landing Page\", \"Phone\"\n  status    LeadStatus @default(NEW)\n  notes     String?    @db.Text\n\n  courseId String? // Formation qui l'interesse\n  course   Course? @relation(fields: [courseId], references: [id])\n\n  /// Fiche catalogue CRM (`Formation`) pour les devis landing â distinct du cours LMS (`courseId`).\n  formationId String?\n  formation   Formation? @relation(\"LeadQuoteFormation\", fields: [formationId], references: [id], onDelete: SetNull)\n\n  candidature    Candidature?\n  financeDevis   FinanceDevis[]\n  supportTickets SupportTicket[]\n  contact        Contact?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@index([status])\n  @@index([formationId])\n}\n\n/// Devis / proposition commerciale (Finance), souvent rattaché à un lead landing devis.\nmodel FinanceDevis {\n  id            String             @id @default(uuid())\n  referenceCode String             @unique\n  title         String\n  status        FinanceDevisStatus @default(DRAFT)\n\n  leadId String?\n  lead   Lead?   @relation(fields: [leadId], references: [id], onDelete: SetNull)\n\n  formationId String?\n  formation   Formation? @relation(fields: [formationId], references: [id], onDelete: SetNull)\n\n  /// Dossier candidature CRM (optionnel) — ex. après conversion lead.\n  candidatureId String?\n  candidature   Candidature? @relation(fields: [candidatureId], references: [id], onDelete: SetNull)\n\n  /// Session catalogue visée (optionnel).\n  formationSessionId String?\n  formationSession   FormationSession? @relation(\"FinanceDevisLinkedSession\", fields: [formationSessionId], references: [id], onDelete: SetNull)\n\n  /// Contexte client figé (entreprise, effectifs, modalité… — aligné formulaire landing).\n  clientSnapshot Json @default(\"{}\")\n  /// Lignes [{ label, quantity, unitPriceHt, vatRate }]\n  lines          Json @default(\"[]\")\n\n  subtotalHt Decimal @default(0) @db.Decimal(12, 2)\n  vatTotal   Decimal @default(0) @db.Decimal(12, 2)\n  totalTtc   Decimal @default(0) @db.Decimal(12, 2)\n  currency   String  @default(\"EUR\")\n\n  validUntil    DateTime?\n  notes         String?   @db.Text\n  internalNotes String?   @db.Text\n\n  /// Facturation électronique (réforme FR 2026) — export Factur-X / envoi PDP.\n  einvoiceStatus       FinanceEinvoiceStatus @default(NOT_READY)\n  /// MINIMUM | BASIC | EN16931 (profil Factur-X).\n  einvoiceProfile      String                @default(\"BASIC\")\n  einvoiceGeneratedAt  DateTime?\n  /// Identifiant retour PDP / plateforme (quand branchée).\n  einvoicePdpMessageId String?\n  einvoiceLastError    String?               @db.Text\n  /// Snapshot XML Factur-X (CII) généré — FileAsset key optionnelle côté storage.\n  einvoiceXmlAssetKey  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  plaquetteMessages FinanceDevisPlaquetteMessage[]\n  payments          FinancePayment[]\n\n  @@index([leadId])\n  @@index([status])\n  @@index([formationId])\n  @@index([candidatureId])\n  @@index([formationSessionId])\n  @@index([einvoiceStatus])\n}\n\n/// Message laissé par le client depuis la plaquette publique (lien signé) — consultable côté CRM.\nmodel FinanceDevisPlaquetteMessage {\n  id          String       @id @default(uuid())\n  devisId     String\n  devis       FinanceDevis @relation(fields: [devisId], references: [id], onDelete: Cascade)\n  /// CLIENT | STAFF (réponses internes futures).\n  authorKind  String       @default(\"CLIENT\")\n  body        String       @db.Text\n  authorLabel String?\n  createdAt   DateTime     @default(now())\n\n  @@index([devisId, createdAt])\n}\n\n/// Lignes préremplies pour les devis : formations catalogue + prestations / frais saisis en base.\nmodel FinanceCatalogLine {\n  id String @id @default(uuid())\n\n  /// FORMATION | PRESTATION | FRAIS | AUTRE\n  category String @default(\"FORMATION\")\n\n  /// Renseigné et unique pour les lignes synchronisées avec une offre catalogue formation.\n  formationId String?    @unique\n  formation   Formation? @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  label       String\n  description String? @db.Text\n\n  defaultUnitPriceHt Decimal? @db.Decimal(12, 2)\n  defaultVatRate     Decimal  @default(20) @db.Decimal(5, 2)\n  currency           String   @default(\"EUR\")\n\n  sortOrder Int     @default(0)\n  isActive  Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isActive, sortOrder])\n  @@index([category, isActive])\n}\n\n// Certifications\nmodel Certification {\n  id       String @id @default(uuid())\n  courseId String\n  config   Json   @default(\"{}\") // Template, logo, signatures, etc.\n\n  course           Course            @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  userCertificates UserCertificate[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([courseId])\n}\n\nmodel UserCertificate {\n  id              String    @id @default(uuid())\n  userId          String\n  certificationId String\n  certificateUrl  String?\n  issueDate       DateTime  @default(now())\n  expiryDate      DateTime?\n\n  user          User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  certification Certification @relation(fields: [certificationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, certificationId])\n  @@index([userId])\n  @@index([certificationId])\n}\n\n// Community & Discussions\nmodel Community {\n  id          String  @id @default(uuid())\n  name        String\n  description String? @db.Text\n  courseId    String? @unique\n\n  course      Course?      @relation(fields: [courseId], references: [id])\n  discussions Discussion[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Discussion {\n  id       String  @id @default(uuid())\n  title    String\n  content  String? @db.Text\n  label    String? @default(\"general\")\n  emoji    String?\n  isPinned Boolean @default(false)\n  isLocked Boolean @default(false)\n\n  authorId    String\n  communityId String\n\n  author    User             @relation(fields: [authorId], references: [id], onDelete: Cascade)\n  community Community        @relation(fields: [communityId], references: [id], onDelete: Cascade)\n  comments  Comment[]\n  votes     DiscussionVote[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([authorId])\n  @@index([communityId])\n}\n\nmodel Comment {\n  id           String  @id @default(uuid())\n  content      String  @db.Text\n  discussionId String\n  authorId     String\n  parentId     String? // Pour les réponses imbriquées\n\n  discussion Discussion    @relation(fields: [discussionId], references: [id], onDelete: Cascade)\n  author     User          @relation(fields: [authorId], references: [id], onDelete: Cascade)\n  parent     Comment?      @relation(\"CommentToComment\", fields: [parentId], references: [id], onDelete: Cascade)\n  replies    Comment[]     @relation(\"CommentToComment\")\n  votes      CommentVote[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([discussionId])\n  @@index([authorId])\n  @@index([parentId])\n}\n\nmodel DiscussionVote {\n  id           String @id @default(uuid())\n  discussionId String\n  userId       String\n  value        Int    @default(1) // 1 pour upvote, -1 pour downvote\n\n  discussion Discussion @relation(fields: [discussionId], references: [id], onDelete: Cascade)\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([discussionId, userId])\n  @@index([discussionId])\n  @@index([userId])\n}\n\nmodel CommentVote {\n  id        String @id @default(uuid())\n  commentId String\n  userId    String\n  value     Int    @default(1)\n\n  comment Comment @relation(fields: [commentId], references: [id], onDelete: Cascade)\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([commentId, userId])\n  @@index([commentId])\n  @@index([userId])\n}\n\n// Assignments\nmodel Assignment {\n  id          String    @id @default(uuid())\n  title       String\n  description String?   @db.Text\n  dueDate     DateTime?\n  maxPoints   Int       @default(100)\n\n  activityId  String                 @unique\n  activity    Activity               @relation(fields: [activityId], references: [id], onDelete: Cascade)\n  submissions AssignmentSubmission[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([activityId])\n}\n\nmodel AssignmentSubmission {\n  id       String  @id @default(uuid())\n  content  String? @db.Text // Texte du rendu ou lien\n  fileUrl  String? // URL du fichier déposé\n  grade    Float?\n  feedback String? @db.Text\n\n  assignmentId String\n  userId       String\n\n  assignment Assignment @relation(fields: [assignmentId], references: [id], onDelete: Cascade)\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([assignmentId, userId])\n  @@index([assignmentId])\n  @@index([userId])\n}\n\n// Billing & Usage Tracking\nmodel ProductPack {\n  id       String @id @default(uuid())\n  type     String // ex: \"ai_credits\", \"member_seats\"\n  packId   String // ex: \"ai_500\", \"basic_subscription\"\n  quantity Int\n  status   String @default(\"active\") // active, cancelled\n\n  activatedAt DateTime  @default(now())\n  cancelledAt DateTime?\n\n  platformSubscriptionId String? // ID Stripe ou autre plateforme\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel UsageEvent {\n  id         String @id @default(uuid())\n  feature    String // ex: \"members\", \"courses\", \"ai_tokens\"\n  eventType  String // ex: \"add\", \"remove\", \"consume\"\n  usageAfter Int // Total après l'événement\n\n  createdAt DateTime @default(now())\n\n  @@index([feature, createdAt])\n}\n\n// Learning Paths & Collections\nmodel Trail {\n  id          String  @id @default(uuid())\n  title       String\n  description String? @db.Text\n  userId      String // Créateur du parcours\n\n  user  User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  steps TrailStep[]\n  runs  TrailRun[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel TrailStep {\n  id       String @id @default(uuid())\n  trailId  String\n  courseId String\n  position Int\n\n  trail  Trail  @relation(fields: [trailId], references: [id], onDelete: Cascade)\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  @@index([trailId])\n  @@index([courseId])\n}\n\nmodel TrailRun {\n  id      String @id @default(uuid())\n  trailId String\n  userId  String\n  status  String @default(\"in_progress\") // in_progress, completed\n\n  trail Trail @relation(fields: [trailId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([trailId])\n  @@index([userId])\n}\n\nmodel Collection {\n  id          String  @id @default(uuid())\n  name        String\n  description String? @db.Text\n  isPublic    Boolean @default(true)\n\n  courses Course[] @relation(\"CourseToCollection\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// External Integrations & Security\nmodel ApiToken {\n  id         String    @id @default(uuid())\n  name       String\n  token      String    @unique\n  userId     String\n  lastUsedAt DateTime?\n  expiresAt  DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel WebhookEndpoint {\n  id          String  @id @default(uuid())\n  url         String\n  secret      String\n  description String?\n  events      Json    @default(\"[]\") // Liste des événements écoutés\n  isActive    Boolean @default(true)\n  createdById String\n\n  createdBy User                 @relation(fields: [createdById], references: [id], onDelete: Cascade)\n  logs      WebhookDeliveryLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([createdById])\n}\n\nmodel WebhookDeliveryLog {\n  id             String  @id @default(uuid())\n  webhookId      String\n  eventName      String\n  payload        Json\n  responseStatus Int?\n  responseBody   String? @db.Text\n  success        Boolean @default(false)\n  duration       Int? // En ms\n\n  webhook WebhookEndpoint @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([webhookId])\n}\n\n// AI & Search (RAG)\nmodel CourseEmbedding {\n  id         String  @id @default(uuid())\n  courseId   String\n  activityId String?\n  chunkText  String  @db.Text\n  embedding  Json? // Remplacé Unsupported(\"vector\") par Json pour compatibilité locale\n\n  course   Course    @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  activity Activity? @relation(fields: [activityId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([courseId])\n  @@index([activityId])\n}\n\n// Collaboration (Hocuspocus/Yjs Persistence)\nmodel CollaborationDocument {\n  id   String @id @default(uuid())\n  name String @unique // Identifiant unique du document (ex: \"chapter-xxx\")\n  data Bytes  @db.ByteA // Le document Yjs sérialisé (State vector)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// --- Support, marketing, SEO, finance (modules CRM opérationnels) ---\n\nenum SupportTicketStatus {\n  OPEN\n  IN_PROGRESS\n  WAITING_CLIENT\n  RESOLVED\n  CLOSED\n}\n\nenum SupportTicketPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nmodel SupportTicket {\n  id             String                @id @default(uuid())\n  referenceCode  String                @unique\n  subject        String\n  description    String                @db.Text\n  status         SupportTicketStatus   @default(OPEN)\n  priority       SupportTicketPriority @default(MEDIUM)\n  requesterName  String\n  requesterEmail String\n  leadId         String?\n  lead           Lead?                 @relation(fields: [leadId], references: [id], onDelete: SetNull)\n  assignedToId   String?\n  assignedTo     User?                 @relation(\"SupportTicketAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  createdById    String?\n  createdBy      User?                 @relation(\"SupportTicketCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  resolvedAt     DateTime?\n  createdAt      DateTime              @default(now())\n  updatedAt      DateTime              @updatedAt\n  comments       TicketComment[]\n  attachments    TicketAttachment[]\n  incidents      QualityIncident[]\n\n  @@index([status])\n  @@index([priority])\n  @@index([leadId])\n  @@index([assignedToId])\n}\n\nmodel TicketComment {\n  id          String             @id @default(uuid())\n  ticketId    String\n  ticket      SupportTicket      @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  authorId    String?\n  author      User?              @relation(\"TicketCommentAuthor\", fields: [authorId], references: [id], onDelete: SetNull)\n  body        String             @db.Text\n  isInternal  Boolean            @default(false)\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n  attachments TicketAttachment[]\n\n  @@index([ticketId])\n  @@index([authorId])\n}\n\nmodel TicketAttachment {\n  id           String         @id @default(uuid())\n  ticketId     String\n  ticket       SupportTicket  @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  commentId    String?\n  comment      TicketComment? @relation(fields: [commentId], references: [id], onDelete: SetNull)\n  fileAssetId  String?\n  fileAsset    FileAsset?     @relation(fields: [fileAssetId], references: [id], onDelete: SetNull)\n  uploadedById String?\n  uploadedBy   User?          @relation(\"TicketAttachmentUploader\", fields: [uploadedById], references: [id], onDelete: SetNull)\n  fileName     String\n  fileUrl      String\n  fileKey      String?\n  mimeType     String?\n  sizeBytes    Int?\n  createdAt    DateTime       @default(now())\n\n  @@index([ticketId])\n  @@index([commentId])\n  @@index([fileAssetId])\n}\n\nenum QualityIncidentSeverity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum QualityIncidentStatus {\n  REPORTED\n  UNDER_ANALYSIS\n  ACTION_IN_PROGRESS\n  /// WF-34 — vérification de l'action corrective avant résolution.\n  AWAITING_VERIFICATION\n  RESOLVED\n  CLOSED\n}\n\nmodel QualityIncident {\n  id               String                  @id @default(uuid())\n  referenceCode    String                  @unique\n  title            String\n  description      String                  @db.Text\n  severity         QualityIncidentSeverity @default(MEDIUM)\n  status           QualityIncidentStatus   @default(REPORTED)\n  category         String?\n  ticketId         String?\n  ticket           SupportTicket?          @relation(fields: [ticketId], references: [id], onDelete: SetNull)\n  equipmentId      String?\n  equipment        Equipment?              @relation(fields: [equipmentId], references: [id], onDelete: SetNull)\n  assignedToId     String?\n  assignedTo       User?                   @relation(\"QualityIncidentAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  reportedById     String?\n  reportedBy       User?                   @relation(\"QualityIncidentReporter\", fields: [reportedById], references: [id], onDelete: SetNull)\n  rootCause        String?                 @db.Text\n  correctiveAction String?                 @db.Text\n  /// WF-34 — échéance de l'action corrective.\n  deadline         DateTime?\n  verifiedAt       DateTime?\n  resolvedAt       DateTime?\n  createdAt        DateTime                @default(now())\n  updatedAt        DateTime                @updatedAt\n\n  @@index([status])\n  @@index([severity])\n  @@index([ticketId])\n  @@index([equipmentId])\n  @@index([assignedToId])\n  @@index([deadline])\n}\n\nenum HelpArticleStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nenum HelpArticleAudience {\n  STAFF\n  FORMATEUR\n  STAGIAIRE\n  PUBLIC\n}\n\nmodel HelpArticle {\n  id           String              @id @default(uuid())\n  title        String\n  slug         String              @unique\n  body         String              @db.Text\n  excerpt      String?             @db.Text\n  category     String              @default(\"general\")\n  audience     HelpArticleAudience @default(STAFF)\n  status       HelpArticleStatus   @default(DRAFT)\n  tags         String[]\n  viewCount    Int                 @default(0)\n  helpfulCount Int                 @default(0)\n  authorId     String?\n  author       User?               @relation(\"HelpArticleAuthor\", fields: [authorId], references: [id], onDelete: SetNull)\n  publishedAt  DateTime?\n  createdAt    DateTime            @default(now())\n  updatedAt    DateTime            @updatedAt\n\n  @@index([status])\n  @@index([category])\n  @@index([audience])\n}\n\nmodel UserNotificationPreference {\n  userId           String   @id\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  email            Boolean  @default(true)\n  inApp            Boolean  @default(true)\n  chat             Boolean  @default(true)\n  desktop          Boolean  @default(true)\n  doNotDisturb     Boolean  @default(false)\n  academicAlerts   Boolean  @default(true)\n  sessionReminders Boolean  @default(true)\n  chatMessages     Boolean  @default(true)\n  updatedAt        DateTime @updatedAt\n}\n\nmodel ModuleSetting {\n  id          String   @id @default(uuid())\n  moduleKey   String\n  settingKey  String\n  value       Json     @default(\"{}\")\n  updatedById String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@unique([moduleKey, settingKey])\n  @@index([moduleKey])\n}\n\nenum MarketingCampaignStatus {\n  DRAFT\n  ACTIVE\n  PAUSED\n  ENDED\n}\n\nmodel MarketingCampaign {\n  id          String                  @id @default(uuid())\n  name        String\n  channel     String                  @default(\"landing\")\n  status      MarketingCampaignStatus @default(DRAFT)\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  startDate   DateTime?\n  endDate     DateTime?\n  notes       String?                 @db.Text\n  createdAt   DateTime                @default(now())\n  updatedAt   DateTime                @updatedAt\n\n  @@index([status])\n  @@index([utmSource])\n}\n\nmodel SeoRedirect {\n  id           String   @id @default(uuid())\n  sourcePath   String   @unique\n  targetPath   String\n  redirectType Int      @default(302)\n  active       Boolean  @default(true)\n  notes        String?  @db.Text\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([active])\n}\n\nenum FinancePaymentStatus {\n  PENDING\n  RECEIVED\n  FAILED\n  REFUNDED\n}\n\nmodel FinancePayment {\n  id            String               @id @default(uuid())\n  referenceCode String               @unique\n  devisId       String?\n  devis         FinanceDevis?        @relation(fields: [devisId], references: [id], onDelete: SetNull)\n  amount        Decimal              @db.Decimal(12, 2)\n  currency      String               @default(\"EUR\")\n  status        FinancePaymentStatus @default(PENDING)\n  method        String?\n  paidAt        DateTime?\n  notes         String?              @db.Text\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n\n  @@index([status])\n  @@index([devisId])\n}\n\nmodel FinanceBudgetLine {\n  id            String   @id @default(uuid())\n  label         String\n  category      String   @default(\"FORMATION\")\n  periodYear    Int\n  periodMonth   Int?\n  plannedAmount Decimal  @db.Decimal(12, 2)\n  actualAmount  Decimal  @default(0) @db.Decimal(12, 2)\n  currency      String   @default(\"EUR\")\n  notes         String?  @db.Text\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([periodYear, periodMonth])\n  @@index([category])\n}\n\nenum InAppNotificationCategory {\n  SYSTEM\n  TICKET\n  FINANCE\n  ACADEMIC\n  TEAM\n}\n\n/// Canal UX simplifié — dossier apprenant, pédagogie, établissement CRM.\nenum InAppNotificationChannel {\n  DOSSIER\n  PEDAGOGIE\n  ETABLISSEMENT\n}\n\n/// File d'événements métier — traitée par `@repo/workers` → `InAppNotification` (+ widgets landing).\nenum CrmEventOutboxStatus {\n  PENDING\n  PROCESSING\n  DONE\n  FAILED\n}\n\nenum CrmEventAudience {\n  BROADCAST_ACTIVE_USERS\n  USER_IDS\n  ROLE_SLUGS\n  PERMISSION_SLUGS\n}\n\nenum CrmEventSeverity {\n  INFO\n  WARNING\n  CRITICAL\n}\n\nmodel CrmEventOutbox {\n  id              String                    @id @default(uuid())\n  eventType       String\n  moduleKey       String\n  specialty       String?\n  category        InAppNotificationCategory\n  severity        CrmEventSeverity          @default(INFO)\n  title           String\n  body            String                    @db.Text\n  href            String?\n  audience        CrmEventAudience          @default(PERMISSION_SLUGS)\n  userIds         String[]                  @default([])\n  roleSlugs       String[]                  @default([])\n  permissionSlugs String[]                  @default([])\n  payload         Json?                     @default(\"{}\")\n  status          CrmEventOutboxStatus      @default(PENDING)\n  error           String?                   @db.Text\n  processedAt     DateTime?\n  createdById     String?\n  createdAt       DateTime                  @default(now())\n\n  @@index([status, createdAt])\n  @@index([moduleKey, createdAt])\n}\n\nmodel InAppNotification {\n  id         String                    @id @default(uuid())\n  userId     String\n  user       User                      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  category   InAppNotificationCategory @default(SYSTEM)\n  channel    InAppNotificationChannel  @default(ETABLISSEMENT)\n  title      String\n  body       String                    @db.Text\n  href       String?\n  readAt     DateTime?\n  archivedAt DateTime?\n  metadata   Json?                     @default(\"{}\")\n  createdAt  DateTime                  @default(now())\n\n  @@index([userId, readAt])\n  @@index([userId, archivedAt])\n  @@index([userId, createdAt])\n  @@index([userId, channel])\n}\n\nenum ChatConversationType {\n  DIRECT\n  GROUP\n}\n\nenum ChatParticipantRole {\n  MEMBER\n  TRAINER\n  MODERATOR\n  OBSERVER\n}\n\nenum ChatInvitationStatus {\n  PENDING\n  ACCEPTED\n  DECLINED\n  CANCELLED\n}\n\nmodel ChatConversation {\n  id                 String               @id @default(uuid())\n  type               ChatConversationType @default(GROUP)\n  title              String?\n  rhTeamId           String?\n  formationSessionId String?              @unique\n  createdAt          DateTime             @default(now())\n  updatedAt          DateTime             @updatedAt\n  rhTeam             RhTeam?              @relation(fields: [rhTeamId], references: [id], onDelete: SetNull)\n  formationSession   FormationSession?    @relation(fields: [formationSessionId], references: [id], onDelete: SetNull)\n  participants       ChatParticipant[]\n  messages           ChatMessage[]\n  invitations        ChatInvitation[]\n\n  @@index([updatedAt])\n  @@index([rhTeamId])\n}\n\nmodel ChatInvitation {\n  id             String               @id @default(uuid())\n  conversationId String\n  inviteeUserId  String\n  invitedById    String\n  status         ChatInvitationStatus @default(PENDING)\n  message        String?              @db.Text\n  expiresAt      DateTime?\n  respondedAt    DateTime?\n  createdAt      DateTime             @default(now())\n  updatedAt      DateTime             @updatedAt\n\n  conversation ChatConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  invitee      User             @relation(\"ChatInvitationInvitee\", fields: [inviteeUserId], references: [id], onDelete: Cascade)\n  invitedBy    User             @relation(\"ChatInvitationInviter\", fields: [invitedById], references: [id], onDelete: Cascade)\n\n  @@unique([conversationId, inviteeUserId])\n  @@index([inviteeUserId, status])\n  @@index([conversationId])\n}\n\nmodel ChatParticipant {\n  id             String              @id @default(uuid())\n  conversationId String\n  userId         String\n  role           ChatParticipantRole @default(MEMBER)\n  lastReadAt     DateTime?\n  joinedAt       DateTime            @default(now())\n  conversation   ChatConversation    @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  user           User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([conversationId, userId])\n  @@index([userId])\n}\n\nmodel ChatMessage {\n  id             String           @id @default(uuid())\n  conversationId String\n  senderId       String\n  body           String           @db.Text\n  createdAt      DateTime         @default(now())\n  conversation   ChatConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  sender         User             @relation(fields: [senderId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId, createdAt])\n  @@index([senderId])\n}\n\n// ─── Conformité documentaire (gouvernance) ───────────────────────────────────\n\nenum ComplianceSubjectType {\n  USER\n  CANDIDATURE\n  COLLABORATEUR\n  FORMATEUR\n  STAGIAIRE\n  SCHOOL\n  FORMATION\n  SESSION\n  E_FORMATION_ENROLLMENT\n  /// WF-39 — subjectId = SubcontractorRecord.id\n  SUBCONTRACTOR\n}\n\nenum ComplianceDossierKind {\n  CANDIDATURE_ADMISSION\n  CANDIDATURE_CNAPS\n  STAGIAIRE_SESSION\n  E_FORMATION_ACCESS\n  COLLABORATEUR_ONBOARDING\n  COLLABORATEUR_RH\n  FORMATEUR_HABILITATION\n  SCHOOL_QUALIOPI\n  SCHOOL_CNAPS_AGREMENT\n  SCHOOL_NDA\n  /// WF-39 pièces qualification sous-traitant\n  SUBCONTRACTOR_QUALIFICATION\n  /// WF-40 actions / procédures référent handicap (sujet SCHOOL)\n  DISABILITY_REFERENT\n}\n\nenum ComplianceDossierStatus {\n  INCOMPLETE\n  COMPLETE\n  EXPIRED\n  WAIVED\n  ARCHIVED\n}\n\nenum ComplianceItemStatus {\n  MISSING\n  REQUESTED\n  RECEIVED\n  VALIDATED\n  REJECTED\n  EXPIRED\n  WAIVED\n}\n\nenum ComplianceUploader {\n  SUBJECT\n  SCHOOL\n  RH\n  ADMIN\n}\n\nenum DocumentRequestStatus {\n  OPEN\n  FULFILLED\n  CANCELLED\n  EXPIRED\n}\n\nenum DocumentRequestChannel {\n  IN_APP\n  EMAIL\n  SMS\n}\n\n/// Catalogue : modèle de dossier par situation métier (admission, CNAPS, onboarding RH…).\nmodel DocumentRequirementTemplate {\n  id          String                @id @default(uuid())\n  kind        ComplianceDossierKind @unique\n  label       String\n  description String?               @db.Text\n  moduleKey   String\n  isActive    Boolean               @default(true)\n  rules       Json?                 @default(\"{}\")\n  createdAt   DateTime              @default(now())\n  updatedAt   DateTime              @updatedAt\n\n  items DocumentRequirementTemplateItem[]\n}\n\nmodel DocumentRequirementTemplateItem {\n  id           String             @id @default(uuid())\n  templateId   String\n  code         String\n  label        String\n  description  String?            @db.Text\n  required     Boolean            @default(true)\n  fileCategory String\n  uploadedBy   ComplianceUploader @default(SUBJECT)\n  expiresField String?\n  sortOrder    Int                @default(0)\n  conditions   Json?              @default(\"{}\")\n\n  template     DocumentRequirementTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  dossierItems ComplianceDossierItem[]\n\n  @@unique([templateId, code])\n  @@index([templateId, sortOrder])\n}\n\n/// Instance de dossier pour un sujet (candidature, user, école…).\nmodel ComplianceDossier {\n  id              String                  @id @default(uuid())\n  kind            ComplianceDossierKind\n  subjectType     ComplianceSubjectType\n  subjectId       String\n  userId          String?\n  candidatureId   String?\n  formationId     String?\n  sessionId       String?\n  status          ComplianceDossierStatus @default(INCOMPLETE)\n  completenessPct Int                     @default(0)\n  dueAt           DateTime?\n  metadata        Json                    @default(\"{}\")\n  createdAt       DateTime                @default(now())\n  updatedAt       DateTime                @updatedAt\n\n  user                User?                   @relation(\"ComplianceDossierUser\", fields: [userId], references: [id], onDelete: SetNull)\n  candidature         Candidature?            @relation(fields: [candidatureId], references: [id], onDelete: Cascade)\n  items               ComplianceDossierItem[]\n  requests            DocumentRequest[]\n  events              ComplianceItemEvent[]\n  subcontractorRecord SubcontractorRecord?\n\n  @@unique([kind, subjectType, subjectId])\n  @@index([userId])\n  @@index([candidatureId])\n  @@index([status])\n  @@index([kind])\n}\n\nmodel ComplianceDossierItem {\n  id                 String               @id @default(uuid())\n  dossierId          String\n  templateItemId     String?\n  code               String\n  label              String\n  fileCategory       String\n  required           Boolean              @default(true)\n  uploadedBy         ComplianceUploader   @default(SUBJECT)\n  status             ComplianceItemStatus @default(MISSING)\n  fileAssetId        String?\n  fileAssetVersionId String?\n  expiresAt          DateTime?\n  validatedAt        DateTime?\n  validatedById      String?\n  rejectionReason    String?              @db.Text\n  lastCheckedAt      DateTime?\n  createdAt          DateTime             @default(now())\n  updatedAt          DateTime             @updatedAt\n\n  dossier      ComplianceDossier                @relation(fields: [dossierId], references: [id], onDelete: Cascade)\n  templateItem DocumentRequirementTemplateItem? @relation(fields: [templateItemId], references: [id], onDelete: SetNull)\n  fileAsset    FileAsset?                       @relation(fields: [fileAssetId], references: [id], onDelete: SetNull)\n  validatedBy  User?                            @relation(\"ComplianceItemValidator\", fields: [validatedById], references: [id], onDelete: SetNull)\n  requests     DocumentRequest[]\n  events       ComplianceItemEvent[]\n\n  @@unique([dossierId, code])\n  @@index([dossierId, status])\n  @@index([fileAssetId])\n}\n\nmodel DocumentRequest {\n  id            String                 @id @default(uuid())\n  dossierId     String\n  dossierItemId String\n  status        DocumentRequestStatus  @default(OPEN)\n  channel       DocumentRequestChannel @default(IN_APP)\n  message       String?                @db.Text\n  dueAt         DateTime?\n  sentAt        DateTime?\n  fulfilledAt   DateTime?\n  requestedById String?\n  createdAt     DateTime               @default(now())\n  updatedAt     DateTime               @updatedAt\n\n  dossier     ComplianceDossier     @relation(fields: [dossierId], references: [id], onDelete: Cascade)\n  dossierItem ComplianceDossierItem @relation(fields: [dossierItemId], references: [id], onDelete: Cascade)\n  requestedBy User?                 @relation(\"DocumentRequestRequester\", fields: [requestedById], references: [id], onDelete: SetNull)\n\n  @@index([dossierId, status])\n  @@index([dossierItemId])\n}\n\nmodel ComplianceItemEvent {\n  id            String   @id @default(uuid())\n  dossierId     String\n  dossierItemId String?\n  eventType     String\n  actorId       String?\n  fileAssetId   String?\n  payload       Json?    @default(\"{}\")\n  createdAt     DateTime @default(now())\n\n  dossier     ComplianceDossier      @relation(fields: [dossierId], references: [id], onDelete: Cascade)\n  dossierItem ComplianceDossierItem? @relation(fields: [dossierItemId], references: [id], onDelete: SetNull)\n  actor       User?                  @relation(\"ComplianceEventActor\", fields: [actorId], references: [id], onDelete: SetNull)\n  fileAsset   FileAsset?             @relation(fields: [fileAssetId], references: [id], onDelete: SetNull)\n\n  @@index([dossierId, createdAt])\n  @@index([dossierItemId])\n}\n\n// ─── Enquête satisfaction stagiaire (GSMS-OF-10) ──────────────────────────────\n\nenum SatisfactionSurveyTiming {\n  HOT\n  COLD\n  /// WF-28 — commanditaire / entreprise\n  COMPANY\n  /// WF-29 — formateur de la session\n  TRAINER\n  /// WF-30 — financeur (OPCO, FT, etc.)\n  FUNDER\n}\n\nenum SatisfactionSurveyStatus {\n  PENDING\n  SENT\n  COMPLETED\n  EXPIRED\n}\n\n/// Enquête de satisfaction — HOT/COLD par participant ; COMPANY/TRAINER/FUNDER\n/// une ligne par session (audienceKey fixe). Réponses en JSON libre.\nmodel SatisfactionSurvey {\n  id             String                   @id @default(uuid())\n  sessionId      String\n  /// Renseigné pour HOT/COLD ; null pour COMPANY/TRAINER/FUNDER.\n  participantId  String?\n  /// Clé d'unicité : participantId (HOT/COLD) ou \"COMPANY\"|\"TRAINER\"|\"FUNDER\".\n  audienceKey    String\n  timing         SatisfactionSurveyTiming\n  status         SatisfactionSurveyStatus @default(PENDING)\n  sentAt         DateTime?\n  respondedAt    DateTime?\n  answers        Json?\n  /// Destinataire stakeholder (COMPANY/TRAINER/FUNDER) ou copie e-mail stagiaire.\n  recipientEmail String?\n  recipientName  String?\n  /// Score moyen 1–4 calculé à la clôture (WF-32) ; null si pas de questions scale.\n  scoreAverage   Float?\n  /// true si score < seuil (alerte Qualiopi / Evidence LOG).\n  scoreAlert     Boolean                  @default(false)\n  createdAt      DateTime                 @default(now())\n  updatedAt      DateTime                 @updatedAt\n\n  session     FormationSession             @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  participant FormationSessionParticipant? @relation(fields: [participantId], references: [id], onDelete: Cascade)\n\n  @@unique([sessionId, timing, audienceKey])\n  @@index([sessionId])\n  @@index([status])\n  @@index([scoreAlert])\n}\n\n// ─── FundingCase (Vague 2 / P0 — post G1-E, gate Claude 2026-08-29) ───────────\n\nenum FundingFunderType {\n  CPF\n  OPCO\n  FRANCE_TRAVAIL\n  AGEFIPH\n  REGION\n  ENTREPRISE\n  TRANSITIONS_PRO\n  /// WF-06 — financement personnel (particulier)\n  SELF_FUNDED\n  /// WF-06 — apprentissage / CFA\n  APPRENTICESHIP\n  OTHER\n}\n\nenum FundingTransport {\n  MANUAL_PORTAL\n  PARTIAL_API\n  VERIFIED_API\n  INTERNAL\n}\n\nenum FundingCaseStatus {\n  DRAFT\n  DOCUMENTS_REQUIRED\n  READY_TO_SUBMIT\n  SUBMITTED\n  PENDING\n  APPROVED\n  PARTIALLY_APPROVED\n  REJECTED\n  SERVICE_IN_PROGRESS\n  SERVICE_COMPLETED\n  JUSTIFICATION_REQUIRED\n  READY_TO_INVOICE\n  INVOICED\n  PAYMENT_PENDING\n  PAID\n  CLOSED\n  CANCELLED\n}\n\nmodel FundingProvider {\n  id         String            @id @default(uuid())\n  code       String            @unique\n  label      String\n  funderType FundingFunderType\n  transport  FundingTransport\n  isActive   Boolean           @default(true)\n  metadata   Json?\n  createdAt  DateTime          @default(now())\n  updatedAt  DateTime          @updatedAt\n  cases      FundingCase[]\n}\n\nmodel FundingCase {\n  id                String                       @id @default(uuid())\n  /// Affichage type FUND-000882 (SERIES naming DocType plus tard)\n  reference         String?                      @unique\n  providerId        String\n  provider          FundingProvider              @relation(fields: [providerId], references: [id])\n  learnerUserId     String?\n  learnerUser       User?                        @relation(\"FundingCaseLearner\", fields: [learnerUserId], references: [id])\n  sessionId         String?\n  session           FormationSession?            @relation(fields: [sessionId], references: [id])\n  participantId     String?\n  participant       FormationSessionParticipant? @relation(fields: [participantId], references: [id])\n  funderType        FundingFunderType\n  transport         FundingTransport\n  status            FundingCaseStatus            @default(DRAFT)\n  externalReference String?\n  requestedAmount   Decimal?                     @db.Decimal(12, 2)\n  approvedAmount    Decimal?                     @db.Decimal(12, 2)\n  currency          String                       @default(\"EUR\")\n  notes             String?\n  ownerUserId       String?\n  createdAt         DateTime                     @default(now())\n  updatedAt         DateTime                     @updatedAt\n  events            FundingCaseEvent[]\n  documents         FundingDocument[]\n\n  @@index([status])\n  @@index([providerId])\n  @@index([sessionId])\n  @@index([learnerUserId])\n}\n\nmodel FundingCaseEvent {\n  id          String             @id @default(uuid())\n  caseId      String\n  case        FundingCase        @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  fromStatus  FundingCaseStatus?\n  toStatus    FundingCaseStatus\n  source      String\n  payload     Json?\n  actorUserId String?\n  createdAt   DateTime           @default(now())\n\n  @@index([caseId, createdAt])\n}\n\nmodel FundingDocument {\n  id          String      @id @default(uuid())\n  caseId      String\n  case        FundingCase @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  code        String\n  label       String\n  status      String\n  fileAssetId String?\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  @@unique([caseId, code])\n  @@index([caseId])\n}\n\n// --- CRM OF G3  Company / Contact / TrainingRequest (Claude gate 2026-08-29) ---\n\nenum CrmCompanyKind {\n  EMPLOYER\n  OPCO_CLIENT\n  PARTNER\n  OTHER\n}\n\nenum TrainingRequestStatus {\n  DRAFT\n  SUBMITTED\n  QUALIFIED\n  ACCEPTED\n  REJECTED\n  CANCELLED\n}\n\nmodel Company {\n  id                   String                @id @default(uuid())\n  name                 String\n  siret                String?\n  kind                 CrmCompanyKind        @default(EMPLOYER)\n  email                String?\n  phone                String?\n  address              String?               @db.Text\n  isActive             Boolean               @default(true)\n  notes                String?               @db.Text\n  contacts             Contact[]\n  trainingRequests     TrainingRequest[]\n  evidences            Evidence[]\n  subcontractorRecords SubcontractorRecord[]\n  createdAt            DateTime              @default(now())\n  updatedAt            DateTime              @updatedAt\n\n  @@index([name])\n  @@index([siret])\n}\n\n/// WF-39 — qualification sous-traitant (cycle de vie ≠ complétude pièces).\nenum SubcontractorQualificationStatus {\n  PENDING_VALIDATION\n  APPROVED\n  ACTIVE\n  REVIEW_REQUIRED\n  SUSPENDED\n}\n\nmodel SubcontractorRecord {\n  id                  String                           @id @default(uuid())\n  companyId           String?\n  company             Company?                         @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  label               String\n  siret               String?\n  status              SubcontractorQualificationStatus @default(PENDING_VALIDATION)\n  notes               String?                          @db.Text\n  complianceDossierId String?                          @unique\n  complianceDossier   ComplianceDossier?               @relation(fields: [complianceDossierId], references: [id], onDelete: SetNull)\n  createdAt           DateTime                         @default(now())\n  updatedAt           DateTime                         @updatedAt\n\n  events SubcontractorStatusEvent[]\n\n  @@index([status])\n  @@index([companyId])\n}\n\nmodel SubcontractorStatusEvent {\n  id              String                            @id @default(uuid())\n  subcontractorId String\n  subcontractor   SubcontractorRecord               @relation(fields: [subcontractorId], references: [id], onDelete: Cascade)\n  fromStatus      SubcontractorQualificationStatus?\n  toStatus        SubcontractorQualificationStatus\n  source          String\n  actorUserId     String?\n  payload         Json?\n  createdAt       DateTime                          @default(now())\n\n  @@index([subcontractorId, createdAt])\n}\n\nmodel Contact {\n  id               String            @id @default(uuid())\n  companyId        String?\n  company          Company?          @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  firstName        String\n  lastName         String\n  email            String?\n  phone            String?\n  jobTitle         String?\n  leadId           String?           @unique\n  lead             Lead?             @relation(fields: [leadId], references: [id], onDelete: SetNull)\n  notes            String?           @db.Text\n  trainingRequests TrainingRequest[]\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n\n  @@index([email])\n  @@index([companyId])\n}\n\n/// Demande de formation B2B / employeur  distincte du Lead individuel landing.\nmodel TrainingRequest {\n  id          String                @id @default(uuid())\n  reference   String?               @unique\n  companyId   String?\n  company     Company?              @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  contactId   String?\n  contact     Contact?              @relation(fields: [contactId], references: [id], onDelete: SetNull)\n  formationId String?\n  formation   Formation?            @relation(fields: [formationId], references: [id], onDelete: SetNull)\n  status      TrainingRequestStatus @default(DRAFT)\n  headcount   Int?\n  notes       String?               @db.Text\n  ownerUserId String?\n  createdAt   DateTime              @default(now())\n  updatedAt   DateTime              @updatedAt\n\n  @@index([status])\n  @@index([companyId])\n  @@index([formationId])\n}\n\n// --- G8 Evidence Engine + SD-06 session readiness (gate Claude 2026-08-29) ---\n\nenum EvidenceSourceType {\n  DOCUMENT\n  EVENT\n  SIGNATURE\n  DATABASE_RECORD\n  EMAIL\n  QUESTIONNAIRE\n  EVALUATION\n  MESSAGE\n  LOG\n  STATISTIQUE\n  HISTORIQUE\n  VALIDATION\n  RELATION\n}\n\nenum EvidenceStatus {\n  PENDING\n  VALID\n  EXPIRED\n  DISPUTED\n  SUPERSEDED\n}\n\nenum SessionReadinessStatus {\n  DRAFT\n  PLANNED\n  CONFIRMED\n  READY\n  RUNNING\n  COMPLETED\n  CLOSED\n  ARCHIVED\n}\n\nmodel Evidence {\n  id                 String             @id @default(uuid())\n  category           String\n  sourceType         EvidenceSourceType\n  sourceId           String\n  status             EvidenceStatus     @default(PENDING)\n  validUntil         DateTime?\n  immutableReference String?            @unique\n\n  sessionId     String?\n  session       FormationSession? @relation(fields: [sessionId], references: [id], onDelete: SetNull)\n  formationId   String?\n  formation     Formation?        @relation(fields: [formationId], references: [id], onDelete: SetNull)\n  learnerUserId String?\n  learner       User?             @relation(\"EvidenceLearner\", fields: [learnerUserId], references: [id], onDelete: SetNull)\n  trainerUserId String?\n  trainer       User?             @relation(\"EvidenceTrainer\", fields: [trainerUserId], references: [id], onDelete: SetNull)\n  companyId     String?\n  company       Company?          @relation(fields: [companyId], references: [id], onDelete: SetNull)\n\n  eventName String?\n  metadata  Json?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  indicatorLinks EvidenceIndicatorLink[]\n\n  @@index([sessionId])\n  @@index([formationId])\n  @@index([learnerUserId])\n  @@index([companyId])\n  @@index([category])\n  @@index([status])\n  @@index([sourceType, sourceId])\n}\n\nmodel EvidenceIndicatorLink {\n  id            String   @id @default(uuid())\n  evidenceId    String\n  evidence      Evidence @relation(fields: [evidenceId], references: [id], onDelete: Cascade)\n  indicatorCode String\n  createdAt     DateTime @default(now())\n\n  @@unique([evidenceId, indicatorCode])\n  @@index([indicatorCode])\n}\n\n/// Audit trail transitions readiness (SD-06) — forçable + findingIds dans payload.\nmodel SessionReadinessEvent {\n  id          String                  @id @default(uuid())\n  sessionId   String\n  session     FormationSession        @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  fromStatus  SessionReadinessStatus?\n  toStatus    SessionReadinessStatus\n  forced      Boolean                 @default(false)\n  source      String\n  actorUserId String?\n  payload     Json?\n  createdAt   DateTime                @default(now())\n\n  @@index([sessionId, createdAt])\n}\n"
}

